import { useState, useRef, useEffect } from "react";
import * as XLSX from "xlsx";
import { createClient } from "@supabase/supabase-js";

const supabase = createClient(import.meta.env.VITE_SUPABASE_URL, import.meta.env.VITE_SUPABASE_KEY);

const TODAY = () => new Date().toLocaleDateString("es-CO");
const HOUR  = () => new Date().toLocaleTimeString("es-CO");
const ID    = () => Date.now().toString(36) + Math.random().toString(36).slice(2,5);

let G = {
  productos: [], usuarios: [], localizaciones: [],
  ubicacionesTipos: ["BODEGA","SALA DE VENTAS"],
  localizacionTipos: ["MUEBLE","LINEAL","NEVERA","PUNTA","JAULA","CAVA"],
  inventario: null, conteos: [], capturas: {}, alertas: [], historial: [],
};

const CAT_C = {"CARNES FRIAS":"#dc2626","CONGELADOS":"#2563eb","SALSAS Y CONSERVAS":"#d97706","LACTEOS Y DERIVADOS":"#0891b2","REPOSTERIA":"#db2777","PANADERIA":"#c2410c","ADOBOS":"#65a30d","CHAMPIÑONES":"#78350f","ACEITES":"#92400e","HARINAS":"#ca8a04","PERECEDEROS":"#16a34a","APANADOS":"#7c2d12"};
const catC = c => CAT_C[c?.trim()] || "#6b7280";

const inp = {width:"100%",padding:"9px 12px",border:"1.5px solid #e2e8f0",borderRadius:8,fontSize:14,boxSizing:"border-box",outline:"none",background:"white",color:"#0f172a"};
const lbl = {fontSize:11,fontWeight:700,color:"#374151",textTransform:"uppercase",letterSpacing:"0.8px",display:"block",marginBottom:5};
const card = {background:"white",borderRadius:12,padding:18,boxShadow:"0 1px 4px rgba(0,0,0,0.07)"};

function Lbl({children,color}){return <label style={{...lbl,...(color?{color}:{})}}>{children}</label>;}
function Inp({value,onChange,placeholder,type="text",disabled,onKeyDown,style={},min}){
  return <input type={type} value={value} onChange={onChange} placeholder={placeholder} disabled={disabled} onKeyDown={onKeyDown} min={min} style={{...inp,...style,background:disabled?"#f8fafc":"white"}}/>;
}
function Sel({value,onChange,children,style={}}){return <select value={value} onChange={onChange} style={{...inp,...style}}>{children}</select>;}
function Btn({c="#2563eb",onClick,disabled,children,full,small,outline}){
  const bg=disabled?"#e2e8f0":outline?"white":c, col=disabled?"#94a3b8":outline?c:"white", border=outline?`1.5px solid ${c}`:"none";
  return <button onClick={onClick} disabled={disabled} style={{padding:small?"5px 12px":"9px 20px",background:bg,color:col,border,borderRadius:8,cursor:disabled?"not-allowed":"pointer",fontWeight:700,fontSize:small?12:13,width:full?"100%":"auto",whiteSpace:"nowrap"}}>{children}</button>;
}
function Badge({color="#6b7280",children,small}){return <span style={{background:color+"22",color,padding:small?"2px 7px":"3px 10px",borderRadius:20,fontSize:small?10:12,fontWeight:700,whiteSpace:"nowrap"}}>{children}</span>;}
function EstBadge({e}){const m={BUENO:["#dcfce7","#166534"],VENCIDO:["#fee2e2","#dc2626"],AVERIADO:["#fef3c7","#92400e"],"NO APTO VENTA":["#fee2e2","#991b1b"],BAJAS:["#fef9c3","#854d0e"],"SIN REVISAR":["#f1f5f9","#475569"]};const[bg,tc]=m[e]||["#f1f5f9","#475569"];return <span style={{background:bg,color:tc,padding:"2px 8px",borderRadius:12,fontSize:11,fontWeight:700}}>{e||"—"}</span>;}
function Modal({titulo,onClose,children,wide}){
  return(<div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.55)",zIndex:1000,display:"flex",alignItems:"flex-start",justifyContent:"center",paddingTop:30,overflowY:"auto",paddingBottom:30}}>
    <div style={{background:"white",borderRadius:16,padding:28,width:wide?680:480,maxWidth:"96vw",boxShadow:"0 25px 60px rgba(0,0,0,0.3)"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
        <h3 style={{margin:0,fontSize:17,fontWeight:700,color:"#0f172a"}}>{titulo}</h3>
        <button onClick={onClose} style={{background:"transparent",border:"none",fontSize:22,cursor:"pointer",color:"#94a3b8",lineHeight:1}}>✕</button>
      </div>{children}</div></div>);
}
function Section({titulo,children}){return(<div style={{marginBottom:22}}><h2 style={{margin:"0 0 16px",fontSize:20,fontWeight:700,color:"#0f172a"}}>{titulo}</h2>{children}</div>);}

const db = {
  async getUsuarios(){const{data}=await supabase.from("usuarios").select("*");return data||[];},
  async upsertUsuario(u){await supabase.from("usuarios").upsert(u,{onConflict:"id"});},
  async deleteUsuario(id){await supabase.from("usuarios").delete().eq("id",id);},
  async getProductos(){const{data}=await supabase.from("productos").select("*");return data||[];},
  async upsertProductos(prods){for(let i=0;i<prods.length;i+=500){await supabase.from("productos").upsert(prods.slice(i,i+500),{onConflict:"id"});}},
  async deleteAllProductos(){await supabase.from("productos").delete().neq("id","__none__");},
  async getInventarios(){const{data}=await supabase.from("inventarios").select("*");return data||[];},
  async upsertInventario(inv){await supabase.from("inventarios").upsert(inv,{onConflict:"id"});},
  async getConteos(){const{data}=await supabase.from("conteos").select("*");return data||[];},
  async upsertConteo(c){await supabase.from("conteos").upsert(c,{onConflict:"id"});},
  async deleteConteo(id){await supabase.from("conteos").delete().eq("id",id);},
};

const serConteo=(c,invId)=>({id:c.id,inventario_id:invId||"",nombre:c.nombre,obs:c.obs||"",tipo:c.tipo,usuario_c1:c.usuarioC1||"",usuario_c2:c.usuarioC2||"",usuario_c3:c.usuarioC3||"",estado:c.estado,loc_label:c.locLabel||"",localizacion_id:c.locId||"",ubicacion:c.ubicacion||"",localizacion_tipo:c.localizacion||"",nro:c.nro||"",fecha_creacion:c.fechaCreacion||TODAY(),rondas_cerradas:JSON.stringify(c.rondasCerradas||[]),capturas_data:JSON.stringify(c.capturas||{})});

export default function TomficApp(){
  const [usuario,setUsuario]=useState(null);
  const [loginForm,setLoginForm]=useState({user:"",pass:""});
  const [loginErr,setLoginErr]=useState("");
  const [,tick]=useState(0);
  const [loading,setLoading]=useState(true);
  const [syncMsg,setSyncMsg]=useState("Cargando datos...");

  const cargarTodo=async()=>{
    try{
      const [usuarios,productos,inventarios,conteos]=await Promise.all([db.getUsuarios(),db.getProductos(),db.getInventarios(),db.getConteos()]);
      if(usuarios.length===0){
        const demos=[{id:"u1",nombre:"ADMIN",pass:"admin123",rol:"admin",activo:true,creado:TODAY()},{id:"u2",nombre:"JUAN",pass:"123",rol:"capturador",activo:true,creado:TODAY()},{id:"u3",nombre:"MARIA",pass:"123",rol:"capturador",activo:true,creado:TODAY()},{id:"u4",nombre:"CARLOS",pass:"123",rol:"capturador",activo:true,creado:TODAY()}];
        for(const u of demos)await db.upsertUsuario(u);G.usuarios=demos;
      } else G.usuarios=usuarios;
      G.productos=productos;
      const invActivo=inventarios.find(i=>i.estado==="abierto");
      G.inventario=invActivo?{...invActivo,horaApertura:invActivo.hora_apertura,usuarioApertura:invActivo.usuario_apertura}:null;
      G.historial=inventarios.filter(i=>i.estado==="cerrado").map(i=>({...i,horaApertura:i.hora_apertura,usuarioApertura:i.usuario_apertura,horaCierre:i.hora_cierre,usuarioCierre:i.usuario_cierre,conteos:i.conteos_snapshot?JSON.parse(i.conteos_snapshot):[],capturas:i.capturas_snapshot?JSON.parse(i.capturas_snapshot):{},productos:i.productos_snapshot?JSON.parse(i.productos_snapshot):[]})).sort((a,b)=>(b.cierre||"").localeCompare(a.cierre||""));
      if(invActivo){
        G.conteos=conteos.filter(c=>c.inventario_id===invActivo.id).map(c=>({...c,usuarioC1:c.usuario_c1,usuarioC2:c.usuario_c2,usuarioC3:c.usuario_c3,locLabel:c.loc_label,locId:c.localizacion_id,localizacion:c.localizacion_tipo,fechaCreacion:c.fecha_creacion,rondasCerradas:c.rondas_cerradas?JSON.parse(c.rondas_cerradas):[],capturas:c.capturas_data?JSON.parse(c.capturas_data):{}}));
        G.capturas={};G.conteos.forEach(c=>{Object.assign(G.capturas,c.capturas||{});});
      } else {G.conteos=[];G.capturas={};}
      try{const loc=localStorage.getItem("tomfic_loc");if(loc){const p=JSON.parse(loc);if(p.localizaciones)G.localizaciones=p.localizaciones;if(p.ubicacionesTipos)G.ubicacionesTipos=p.ubicacionesTipos;if(p.localizacionTipos)G.localizacionTipos=p.localizacionTipos;}}catch(e){}
    }catch(err){console.error(err);setSyncMsg("Error de conexión");}
  };

  useEffect(()=>{(async()=>{await cargarTodo();setLoading(false);})();},[]);

  const saveLoc=()=>{try{localStorage.setItem("tomfic_loc",JSON.stringify({localizaciones:G.localizaciones,ubicacionesTipos:G.ubicacionesTipos,localizacionTipos:G.localizacionTipos}));}catch(e){}};
  const rerender=()=>tick(n=>n+1);
  const recargar=async()=>{await cargarTodo();rerender();};
  const toastRef=useRef(null);
  const [toast,setToast]=useState(null);
  const showToast=(msg,type="ok")=>{setToast({msg,type});if(toastRef.current)clearTimeout(toastRef.current);toastRef.current=setTimeout(()=>setToast(null),3500);};

  const login=()=>{const u=loginForm.user.toUpperCase().trim();const found=G.usuarios.find(x=>x.nombre===u&&x.pass===loginForm.pass&&x.activo);if(found){setUsuario(found);setLoginErr("");}else setLoginErr("Usuario o contraseña incorrectos");};

  if(loading)return(<div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:"#0f172a",fontFamily:"system-ui,sans-serif"}}><div style={{textAlign:"center",color:"white"}}><div style={{fontSize:52,marginBottom:16}}>📦</div><div style={{fontSize:24,fontWeight:900,marginBottom:8}}>TOMFIC</div><div style={{fontSize:14,color:"#64748b"}}>{syncMsg}</div><div style={{marginTop:20,width:200,height:4,background:"#1e293b",borderRadius:99,overflow:"hidden",margin:"20px auto 0"}}><div style={{width:"60%",height:"100%",background:"linear-gradient(90deg,#2563eb,#16a34a)",borderRadius:99}}/></div></div></div>);

  if(!usuario)return <Login lf={loginForm} setLf={setLoginForm} err={loginErr} onLogin={login}/>;
  const p={usuario,setUsuario,G,rerender,recargar,showToast,db,saveLoc};
  return(<>{toast&&<div style={{position:"fixed",top:58,right:20,background:toast.type==="err"?"#dc2626":toast.type==="warn"?"#d97706":"#16a34a",color:"white",padding:"10px 20px",borderRadius:10,zIndex:9999,fontSize:14,fontWeight:700,boxShadow:"0 4px 20px rgba(0,0,0,0.2)",pointerEvents:"none",maxWidth:360}}>{toast.msg}</div>}{usuario.rol==="capturador"?<ModCapturador {...p}/>:<ModAdmin {...p}/>}</>);
}

