          <div style={{marginBottom:20}}><Lbl>Contraseña</Lbl><div style={{position:"relative"}}><input type={showPass?"text":"password"} value={lf.pass} onChange={e=>setLf(p=>({...p,pass:e.target.value}))} onKeyDown={e=>e.key==="Enter"&&onLogin()} placeholder="••••••••" style={{...inp,paddingRight:44,fontSize:15}}/><button onClick={()=>setShowPass(v=>!v)} style={{position:"absolute",right:12,top:"50%",transform:"translateY(-50%)",background:"transparent",border:"none",cursor:"pointer",fontSize:18,color:"#94a3b8"}}>{showPass?"🙈":"👁"}</button></div></div>
