          <button onClick={onLogin} style={{width:"100%",padding:"13px",background:"linear-gradient(135deg,#1e40af,#2563eb)",color:"white",border:"none",borderRadius:10,fontSize:16,fontWeight:700,cursor:"pointer"}}>Ingresar al sistema →</button>
