function ModAdmin({usuario,setUsuario,G,rerender,recargar,showToast,db,saveLoc}){
  const [view,setView]=useState("inventario");
  const alertas=G.alertas.filter(a=>!a.leida).length;
  const nav=[{id:"inventario",icon:"📋",label:"Inventario"},{id:"ubicaciones",icon:"📍",label:"Ubicaciones"},{id:"basedatos",icon:"🗄️",label:"Base de datos"},{id:"conteos",icon:"🗂️",label:"Conteos"},{id:"procesos",icon:"📡",label:"Procesos"},{id:"reportes",icon:"📊",label:"Reportes"},{id:"usuarios",icon:"👥",label:"Usuarios"},{id:"historial",icon:"🗄️",label:"Historial"}];
  const props={usuario,setUsuario,G,rerender,recargar,showToast,db,saveLoc};
  return(<div style={{minHeight:"100vh",background:"#f1f5f9",fontFamily:"system-ui,sans-serif"}}>
    <div style={{background:"#0f172a",color:"white",padding:"0 20px",display:"flex",alignItems:"center",justifyContent:"space-between",height:54,position:"sticky",top:0,zIndex:100}}>
      <div style={{display:"flex",alignItems:"center",gap:12}}><span style={{fontSize:20}}>📦</span><span style={{fontWeight:800,fontSize:16}}>TOMFIC</span><span style={{color:"#475569",fontSize:12}}>Admin</span>{G.inventario&&<span style={{background:"#16a34a",fontSize:10,padding:"2px 10px",borderRadius:20,fontWeight:700}}>● {G.inventario.nombre}</span>}</div>
      <div style={{display:"flex",gap:10,alignItems:"center"}}>
        <button onClick={recargar} style={{background:"transparent",border:"1px solid #334155",color:"#94a3b8",padding:"4px 10px",borderRadius:6,fontSize:11,cursor:"pointer"}}>🔄 Actualizar</button>
        {alertas>0&&<button onClick={()=>{G.alertas=G.alertas.map(a=>({...a,leida:true}));rerender();setView("procesos");}} style={{background:"#dc2626",color:"white",border:"none",padding:"5px 12px",borderRadius:8,cursor:"pointer",fontSize:12,fontWeight:700}}>🔔 {alertas}</button>}
        <span style={{fontSize:12,color:"#94a3b8"}}>👤 {usuario.nombre}</span>
        <button onClick={()=>setUsuario(null)} style={{background:"transparent",border:"1px solid #334155",color:"#94a3b8",padding:"4px 10px",borderRadius:6,fontSize:11,cursor:"pointer"}}>Salir</button>
      </div>
    </div>
    <div style={{display:"flex",minHeight:"calc(100vh - 54px)"}}>
      <div style={{width:190,background:"#1e293b",padding:"14px 0",flexShrink:0,position:"sticky",top:54,height:"calc(100vh - 54px)",overflowY:"auto"}}>
        {nav.map(n=>(<button key={n.id} onClick={()=>setView(n.id)} style={{width:"100%",display:"flex",alignItems:"center",gap:9,padding:"10px 16px",background:view===n.id?"#2563eb":"transparent",color:view===n.id?"white":"#94a3b8",border:"none",cursor:"pointer",fontSize:13,textAlign:"left"}}><span>{n.icon}</span><span>{n.label}</span></button>))}
      </div>
      <div style={{flex:1,padding:22,overflowY:"auto"}}>
        {view==="inventario"&&<VInventario {...props}/>}
        {view==="ubicaciones"&&<VUbicaciones {...props}/>}
        {view==="basedatos"&&<VBaseDatos {...props}/>}
        {view==="conteos"&&<VConteos {...props}/>}
        {view==="procesos"&&<VProcesos {...props}/>}
        {view==="reportes"&&<VReportes {...props}/>}
        {view==="usuarios"&&<VUsuarios {...props}/>}
        {view==="historial"&&<VHistorial {...props}/>}
      </div>
    </div>
  </div>);
}

function VInventario({G,rerender,showToast,usuario,db}){
  const [modal,setModal]=useState(false);const [modalEdit,setModalEdit]=useState(false);
  const [form,setForm]=useState({nombre:"",tipo:"2conteos",obs:"",fecha:TODAY()});
  const [editForm,setEditForm]=useState({nombre:"",obs:""});const [saving,setSaving]=useState(false);
  const crear=async()=>{
    if(!form.nombre.trim())return showToast("Ingresa un nombre","err");
    if(G.inventario)return showToast("Ya hay un inventario activo","err");
    setSaving(true);
    const inv={id:ID(),nombre:form.nombre,tipo:form.tipo,obs:form.obs,fecha:form.fecha,apertura:TODAY(),hora_apertura:HOUR(),usuario_apertura:usuario.nombre,estado:"abierto",conteos_snapshot:null,capturas_snapshot:null,productos_snapshot:null};
    await db.upsertInventario(inv);G.inventario={...inv,horaApertura:inv.hora_apertura,usuarioApertura:inv.usuario_apertura};G.conteos=[];G.capturas={};G.alertas=[];
    setModal(false);setForm({nombre:"",tipo:"2conteos",obs:"",fecha:TODAY()});setSaving(false);rerender();showToast("Inventario creado ✓");
  };
  const guardarEdit=async()=>{if(!editForm.nombre.trim())return showToast("Nombre vacío","err");setSaving(true);const u={...G.inventario,nombre:editForm.nombre,obs:editForm.obs};await db.upsertInventario(u);G.inventario=u;setModalEdit(false);setSaving(false);rerender();showToast("Actualizado ✓");};
  const cerrar=async()=>{
    if(!G.inventario)return;setSaving(true);
    const capsSnap=JSON.parse(JSON.stringify(G.capturas)),prodsSnap=JSON.parse(JSON.stringify(G.productos)),conteosSnap=JSON.parse(JSON.stringify(G.conteos));
    const closed={...G.inventario,estado:"cerrado",cierre:TODAY(),hora_cierre:HOUR(),usuario_cierre:usuario.nombre,conteos_snapshot:JSON.stringify(conteosSnap),capturas_snapshot:JSON.stringify(capsSnap),productos_snapshot:JSON.stringify(prodsSnap)};
    await db.upsertInventario(closed);
    G.historial.unshift({...closed,horaCierre:closed.hora_cierre,usuarioCierre:closed.usuario_cierre,conteos:conteosSnap,capturas:capsSnap,productos:prodsSnap});
    G.productos=G.productos.map(p=>{const caps=Object.values(G.capturas).filter(c=>c.productoId===p.id);const s3=caps.filter(c=>c.ronda==="C3").reduce((s,c)=>s+c.cantidad,0),s2=caps.filter(c=>c.ronda==="C2").reduce((s,c)=>s+c.cantidad,0),s1=caps.filter(c=>c.ronda==="C1").reduce((s,c)=>s+c.cantidad,0);const f=s3||s2||s1;return f>0?{...p,saldo:f}:p;});
    await db.upsertProductos(G.productos);
    for(const c of G.conteos)await db.deleteConteo(c.id);
    G.inventario=null;G.conteos=[];G.capturas={};G.alertas=[];setSaving(false);rerender();showToast("Inventario cerrado ✓");
  };
  const st=G.conteos.reduce((a,c)=>{if(["completado","cerradoC2"].includes(c.estado))a.comp++;if(c.estado==="diferencia")a.dif++;return a;},{comp:0,dif:0});
  return(<Section titulo="Inventario">
    <div style={{display:"flex",gap:10,marginBottom:16}}>
      {!G.inventario&&<Btn c="#16a34a" onClick={()=>setModal(true)} disabled={saving}>+ Nuevo Inventario</Btn>}
      {G.inventario&&<Btn c="#dc2626" onClick={cerrar} disabled={saving}>⬛ Cerrar Inventario</Btn>}
      {G.inventario&&<Btn c="#2563eb" outline onClick={()=>{setEditForm({nombre:G.inventario.nombre,obs:G.inventario.obs||""});setModalEdit(true);}}>✏️ Editar</Btn>}
    </div>
    {!G.inventario?(<div style={{...card,textAlign:"center",padding:48,color:"#64748b"}}><div style={{fontSize:52,marginBottom:12}}>📋</div><div style={{fontSize:15,fontWeight:600,marginBottom:6}}>No hay inventario activo</div><div style={{fontSize:13}}>Crea uno nuevo para comenzar.</div></div>):(
      <div style={card}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}><div><div style={{fontSize:20,fontWeight:800,color:"#0f172a"}}>{G.inventario.nombre}</div><div style={{fontSize:13,color:"#64748b",marginTop:4}}>Abierto: {G.inventario.apertura} · por {G.inventario.usuarioApertura}</div></div><Badge color="#16a34a">● ACTIVO</Badge></div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(130px,1fr))",gap:12}}>{[{l:"Tipo",v:G.inventario.tipo==="2conteos"?"2 Conteos":"1 Conteo"},{l:"Fecha",v:G.inventario.fecha},{l:"Productos",v:G.productos.length},{l:"Conteos",v:G.conteos.length},{l:"Completados",v:st.comp},{l:"Con diferencia",v:st.dif}].map(s=>(<div key={s.l} style={{background:"#f8fafc",borderRadius:8,padding:"10px 14px"}}><div style={{fontSize:11,color:"#64748b",marginBottom:3}}>{s.l}</div><div style={{fontSize:17,fontWeight:700,color:"#0f172a"}}>{s.v}</div></div>))}</div>
        {G.productos.length===0&&<div style={{marginTop:14,background:"#fef9c3",border:"1px solid #fde047",borderRadius:8,padding:"10px 14px",fontSize:13,color:"#92400e",fontWeight:600}}>⚠️ Base vacía — carga el Excel en "Base de datos".</div>}
        {G.productos.length>0&&<div style={{marginTop:14,background:"#f0fdf4",border:"1px solid #bbf7d0",borderRadius:8,padding:"10px 14px",fontSize:13,color:"#166534",fontWeight:600}}>✅ {G.productos.length} productos disponibles.</div>}
      </div>
    )}
    {modal&&(<Modal titulo="Nuevo Inventario" onClose={()=>setModal(false)}>
      <Lbl>Nombre</Lbl><Inp value={form.nombre} onChange={e=>setForm(p=>({...p,nombre:e.target.value}))} placeholder="Ej: Inventario General Junio 2025" style={{marginBottom:14}}/>
      <Lbl>Fecha</Lbl><Inp value={form.fecha} onChange={e=>setForm(p=>({...p,fecha:e.target.value}))} style={{marginBottom:14}}/>
      <Lbl>Tipo de conteo</Lbl><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:14}}>{[["1conteo","1 Conteo","Un solo pase"],["2conteos","2 Conteos","C1 + C2 + C3"]].map(([v,t,s])=>(<div key={v} onClick={()=>setForm(p=>({...p,tipo:v}))} style={{border:`2px solid ${form.tipo===v?"#2563eb":"#e2e8f0"}`,borderRadius:10,padding:12,cursor:"pointer",background:form.tipo===v?"#eff6ff":"white"}}><div style={{fontWeight:700,color:form.tipo===v?"#2563eb":"#0f172a",fontSize:14}}>{t}</div><div style={{fontSize:11,color:"#64748b",marginTop:2}}>{s}</div></div>))}</div>
      <Lbl>Observaciones</Lbl><Inp value={form.obs} onChange={e=>setForm(p=>({...p,obs:e.target.value}))} placeholder="Opcional..." style={{marginBottom:20}}/>
      <Btn c="#16a34a" onClick={crear} full disabled={saving}>{saving?"Guardando...":"✓ Crear Inventario"}</Btn>
    </Modal>)}
    {modalEdit&&(<Modal titulo="Editar Inventario" onClose={()=>setModalEdit(false)}><Lbl>Nombre</Lbl><Inp value={editForm.nombre} onChange={e=>setEditForm(p=>({...p,nombre:e.target.value}))} style={{marginBottom:14}}/><Lbl>Observaciones</Lbl><Inp value={editForm.obs} onChange={e=>setEditForm(p=>({...p,obs:e.target.value}))} placeholder="Opcional..." style={{marginBottom:20}}/><Btn c="#2563eb" onClick={guardarEdit} full disabled={saving}>{saving?"Guardando...":"✓ Guardar"}</Btn></Modal>)}
  </Section>);
}

function VUbicaciones({G,rerender,showToast,saveLoc}){
  const [form,setForm]=useState({ubicacion:"",localizacion:"",nro:"",observacion:""});
  const [nU,setNU]=useState("");const [nL,setNL]=useState("");
  const sNro=()=>{if(!form.ubicacion||!form.localizacion)return "";const ex=G.localizaciones.filter(l=>l.ubicacion===form.ubicacion&&l.localizacion===form.localizacion);return `${form.localizacion} ${ex.length+1}`;};
  const agregar=()=>{if(!form.ubicacion||!form.localizacion)return showToast("Selecciona ubicación y localización","err");const nro=form.nro||sNro();if(G.localizaciones.find(l=>l.ubicacion===form.ubicacion&&l.localizacion===form.localizacion&&l.nro===nro))return showToast("Ya existe","err");G.localizaciones.push({id:ID(),ubicacion:form.ubicacion,localizacion:form.localizacion,nro,observacion:form.observacion});setForm(p=>({...p,nro:"",observacion:""}));saveLoc();rerender();showToast("Agregada ✓");};
  const eliminar=(id)=>{G.localizaciones=G.localizaciones.filter(l=>l.id!==id);saveLoc();rerender();showToast("Eliminada ✓","warn");};
  const aU=()=>{const n=nU.trim().toUpperCase();if(!n||G.ubicacionesTipos.includes(n))return;G.ubicacionesTipos.push(n);setNU("");saveLoc();rerender();};
  const aL=()=>{const n=nL.trim().toUpperCase();if(!n||G.localizacionTipos.includes(n))return;G.localizacionTipos.push(n);setNL("");saveLoc();rerender();};
  return(<Section titulo="Ubicaciones y Localizaciones">
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:18}}>
      <div style={card}><div style={{fontSize:13,fontWeight:700,marginBottom:10}}>Tipos de Ubicación</div><div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:10}}>{G.ubicacionesTipos.map(u=><Badge key={u} color="#2563eb">{u}</Badge>)}</div><div style={{display:"flex",gap:8}}><Inp value={nU} onChange={e=>setNU(e.target.value.toUpperCase())} placeholder="Ej: BODEGA" onKeyDown={e=>e.key==="Enter"&&aU()} style={{flex:1}}/><Btn c="#16a34a" small onClick={aU}>+</Btn></div></div>
      <div style={card}><div style={{fontSize:13,fontWeight:700,marginBottom:10}}>Tipos de Localización</div><div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:10}}>{G.localizacionTipos.map(l=><Badge key={l} color="#d97706">{l}</Badge>)}</div><div style={{display:"flex",gap:8}}><Inp value={nL} onChange={e=>setNL(e.target.value.toUpperCase())} placeholder="Ej: MUEBLE" onKeyDown={e=>e.key==="Enter"&&aL()} style={{flex:1}}/><Btn c="#16a34a" small onClick={aL}>+</Btn></div></div>
    </div>
    <div style={{...card,marginBottom:18}}><div style={{fontSize:13,fontWeight:700,marginBottom:12}}>Agregar nueva localización</div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr auto",gap:10,alignItems:"end"}}>
        <div><Lbl>Ubicación</Lbl><Sel value={form.ubicacion} onChange={e=>setForm(p=>({...p,ubicacion:e.target.value,nro:""}))}><option value="">Seleccionar…</option>{G.ubicacionesTipos.map(u=><option key={u}>{u}</option>)}</Sel></div>
        <div><Lbl>Localización</Lbl><Sel value={form.localizacion} onChange={e=>setForm(p=>({...p,localizacion:e.target.value,nro:""}))}><option value="">Seleccionar…</option>{G.localizacionTipos.map(l=><option key={l}>{l}</option>)}</Sel></div>
        <div><Lbl>N° (auto)</Lbl><Inp value={form.nro} onChange={e=>setForm(p=>({...p,nro:e.target.value.toUpperCase()}))} placeholder={sNro()||"Auto"}/></div>
        <div><Lbl>Observación</Lbl><Inp value={form.observacion} onChange={e=>setForm(p=>({...p,observacion:e.target.value}))} placeholder="Ej: DETERGENTES"/></div>
        <div><Btn c="#16a34a" onClick={agregar}>+ Agregar</Btn></div>
      </div>
    </div>
    <div style={card}><div style={{fontSize:13,fontWeight:700,marginBottom:12}}>Localizaciones ({G.localizaciones.length})</div>
      {G.localizaciones.length>0&&(<div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}><thead><tr style={{background:"#0f172a",color:"white"}}>{["Ubicación","Localización","N°","Observación",""].map(h=><th key={h} style={{padding:"8px 12px",textAlign:"left",fontWeight:600}}>{h}</th>)}</tr></thead><tbody>{G.localizaciones.map((l,i)=>(<tr key={l.id} style={{background:i%2?"#f8fafc":"white",borderBottom:"1px solid #f1f5f9"}}><td style={{padding:"7px 12px",fontWeight:700,color:"#2563eb"}}>{l.ubicacion}</td><td style={{padding:"7px 12px",color:"#64748b"}}>{l.localizacion}</td><td style={{padding:"7px 12px",fontWeight:600}}>{l.nro}</td><td style={{padding:"7px 12px",color:"#64748b"}}>{l.observacion||"—"}</td><td style={{padding:"7px 12px"}}><button onClick={()=>eliminar(l.id)} style={{background:"transparent",border:"none",color:"#dc2626",cursor:"pointer",fontWeight:700,fontSize:15}}>✕</button></td></tr>))}</tbody></table></div>)}
    </div>
  </Section>);
}

function VBaseDatos({G,rerender,showToast,db}){
  const [search,setSearch]=useState("");const [catF,setCatF]=useState("");const [preview,setPreview]=useState(null);const [rawData,setRawData]=useState(null);const [importing,setImporting]=useState(false);
  const cargarPreview=(e)=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=(ev)=>{const wb=XLSX.read(ev.target.result,{type:"binary"});const ws=wb.Sheets[wb.SheetNames[0]];const data=XLSX.utils.sheet_to_json(ws,{defval:""});if(!data.length)return showToast("Archivo vacío","err");setRawData(data);setPreview(data.slice(0,8));};reader.readAsBinaryString(file);e.target.value="";};
  const confirmarImport=async()=>{
    if(!rawData)return;setImporting(true);
    const norm=(row)=>{const n={};Object.keys(row).forEach(k=>{n[k.trim()]=row[k];});return n;};
    const mapped=rawData.map((rr,i)=>{const row=norm(rr);const get=(...keys)=>{for(const k of keys){if(row[k]!==undefined&&row[k]!==null&&String(row[k]).trim()!=="")return String(row[k]).trim();}return "";};return{id:"p"+i,ean:get("EAN13","CODIGOBARRAS","ean"),codigo:get("CODIGO","CODIGOINTERNO","codigo"),nombre:get("NOMBRE PRODUCTO","nombre","NOMBRE"),referencia:get("NOMBRE REFERENCIA","referencia"),categoria:get("NOMBRE CATEGORIA","categoria"),subcategoria:get("NOMBRE SUBCATEGORIA","subcategoria"),subgrupo:get("NOMBRE SUBGRUPO","subgrupo"),determinada:get("NOMBRE DETERMINADA","determinada"),saldo:parseFloat(row.SALDO||row.CANTIDAD||row.saldo||0)||0,costo:parseFloat(row.COSTO||row.costo||0)||0,nit:get("NIT","nit"),proveedor:get("NOMBRE PROVEEDOR","proveedor")};}).filter(r=>r.nombre);
    await db.deleteAllProductos();await db.upsertProductos(mapped);G.productos=mapped;setPreview(null);setRawData(null);setImporting(false);rerender();showToast(`✓ ${mapped.length} productos importados`);
  };
  const cats=[...new Set(G.productos.map(p=>p.categoria).filter(Boolean))].sort();
  const filtrados=G.productos.filter(p=>{const q=search.toLowerCase();return(!q||(p.nombre.toLowerCase().includes(q)||p.ean.includes(q)||p.codigo.toLowerCase().includes(q)))&&(!catF||p.categoria===catF);});
  return(<Section titulo="Base de Productos">
    <div style={{display:"flex",gap:10,marginBottom:16,alignItems:"center",flexWrap:"wrap"}}>
      <label style={{padding:"9px 20px",background:"#2563eb",color:"white",borderRadius:8,cursor:"pointer",fontWeight:700,fontSize:13}}>⬆ Cargar / Actualizar Excel<input type="file" accept=".xlsx,.xls" onChange={cargarPreview} style={{display:"none"}}/></label>
      {G.productos.length>0&&(<><div style={{padding:"9px 14px",background:"#f0fdf4",color:"#166534",borderRadius:8,fontSize:13,fontWeight:700,border:"1px solid #bbf7d0"}}>✅ {G.productos.length} productos</div><button onClick={async()=>{await db.deleteAllProductos();G.productos=[];rerender();showToast("Base limpiada","warn");}} style={{padding:"9px 14px",background:"#fef2f2",color:"#dc2626",border:"1px solid #fecaca",borderRadius:8,fontSize:13,fontWeight:700,cursor:"pointer"}}>🗑 Limpiar</button></>)}
      {G.productos.length===0&&!preview&&<div style={{background:"#fef9c3",borderRadius:8,padding:"8px 14px",fontSize:13,color:"#92400e",fontWeight:600}}>⚠️ Base vacía — carga el Excel</div>}
    </div>
    {preview&&(<div style={{...card,marginBottom:16,border:"2px solid #2563eb"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}><div style={{fontWeight:700,fontSize:15,color:"#1e40af"}}>Vista previa — {rawData.length} filas</div><div style={{display:"flex",gap:10}}><Btn c="#dc2626" outline onClick={()=>{setPreview(null);setRawData(null);}}>Cancelar</Btn><Btn c="#16a34a" onClick={confirmarImport} disabled={importing}>{importing?"Importando...":"✓ Confirmar"}</Btn></div></div><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead><tr style={{background:"#eff6ff"}}>{Object.keys(preview[0]||{}).slice(0,10).map(k=><th key={k} style={{padding:"7px 10px",textAlign:"left",fontWeight:700,color:"#1e40af",borderBottom:"2px solid #bfdbfe",whiteSpace:"nowrap"}}>{k}</th>)}</tr></thead><tbody>{preview.map((row,i)=><tr key={i} style={{background:i%2?"#f8fafc":"white"}}>{Object.keys(row).slice(0,10).map(k=><td key={k} style={{padding:"6px 10px"}}>{String(row[k]).substring(0,30)}</td>)}</tr>)}</tbody></table></div></div>)}
    {G.productos.length>0&&(<><div style={{display:"flex",gap:12,marginBottom:14,flexWrap:"wrap"}}><Inp value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar nombre, código, EAN…" style={{flex:1,minWidth:200}}/><Sel value={catF} onChange={e=>setCatF(e.target.value)} style={{width:"auto",minWidth:180}}><option value="">Todas las categorías</option>{cats.map(c=><option key={c}>{c}</option>)}</Sel><div style={{padding:"9px 14px",background:"#e0f2fe",color:"#0369a1",borderRadius:8,fontSize:13,fontWeight:700}}>{filtrados.length}</div></div>
    <div style={{...card,padding:0,overflow:"hidden"}}><div style={{overflowX:"auto",maxHeight:500}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead style={{position:"sticky",top:0}}><tr style={{background:"#0f172a",color:"white"}}>{["Código","EAN","Nombre","Referencia","Categoría","Proveedor","Saldo","Costo"].map(h=><th key={h} style={{padding:"9px 11px",textAlign:"left",fontWeight:600,whiteSpace:"nowrap"}}>{h}</th>)}</tr></thead><tbody>{filtrados.slice(0,500).map((p,i)=>(<tr key={p.id} style={{background:i%2?"#f8fafc":"white",borderBottom:"1px solid #f1f5f9"}}><td style={{padding:"6px 11px",fontFamily:"monospace",color:"#2563eb",fontWeight:700}}>{p.codigo}</td><td style={{padding:"6px 11px",color:"#94a3b8",fontSize:10}}>{p.ean}</td><td style={{padding:"6px 11px",fontWeight:500}}>{p.nombre}</td><td style={{padding:"6px 11px",color:"#64748b"}}>{p.referencia}</td><td style={{padding:"6px 11px"}}><Badge color={catC(p.categoria)} small>{p.categoria||"—"}</Badge></td><td style={{padding:"6px 11px",color:"#64748b"}}>{p.proveedor||"—"}</td><td style={{padding:"6px 11px",textAlign:"center",fontWeight:700,color:p.saldo>0?"#16a34a":"#94a3b8"}}>{p.saldo}</td><td style={{padding:"6px 11px",textAlign:"right",color:"#64748b"}}>{p.costo>0?"$"+p.costo.toLocaleString("es-CO"):"—"}</td></tr>))}</tbody></table></div></div></>)}
  </Section>);
}

function VConteos({G,rerender,showToast,db}){
  const [modal,setModal]=useState(false);const [modalMod,setModalMod]=useState(null);
  const [form,setForm]=useState({nombre:"",locId:"",usuarioC1:"",usuarioC2:""});
  const [modForm,setModForm]=useState({obs:"",usuarioC1:"",usuarioC2:""});const [saving,setSaving]=useState(false);
  const crear=async()=>{
    if(!G.inventario)return showToast("Primero crea un inventario","err");
    if(!form.nombre.trim()||!form.locId||!form.usuarioC1)return showToast("Completa nombre, localización y usuario C1","err");
    setSaving(true);const loc=G.localizaciones.find(l=>l.id===form.locId);
    const nuevo={id:ID(),nombre:form.nombre,locId:form.locId,locLabel:`${loc.ubicacion} › ${loc.localizacion} › ${loc.nro}`,ubicacion:loc.ubicacion,localizacion:loc.localizacion,nro:loc.nro,obs:"",tipo:G.inventario.tipo,usuarioC1:form.usuarioC1,usuarioC2:form.usuarioC2||"",usuarioC3:"",estado:"pendiente",rondasCerradas:[],fechaCreacion:TODAY(),capturas:{}};
    await db.upsertConteo(serConteo(nuevo,G.inventario.id));G.conteos.push(nuevo);setModal(false);setForm({nombre:"",locId:"",usuarioC1:"",usuarioC2:""});setSaving(false);rerender();showToast("Conteo programado ✓");
  };
  const guardarMod=async()=>{if(!modForm.usuarioC1)return showToast("Usuario C1 requerido","err");setSaving(true);G.conteos=G.conteos.map(c=>c.id===modalMod.id?{...c,obs:modForm.obs,usuarioC1:modForm.usuarioC1,usuarioC2:modForm.usuarioC2}:c);await db.upsertConteo(serConteo(G.conteos.find(c=>c.id===modalMod.id),G.inventario?.id));setModalMod(null);setSaving(false);rerender();showToast("Actualizado ✓");};
  const reabrir=async(id)=>{G.conteos=G.conteos.map(c=>c.id===id?{...c,estado:"enCurso",rondasCerradas:[]}:c);await db.upsertConteo(serConteo(G.conteos.find(c=>c.id===id),G.inventario?.id));rerender();showToast("Reabierto ✓","warn");};
  const stC={pendiente:"#94a3b8",enCurso:"#2563eb",cerradoC1:"#d97706",cerradoC2:"#16a34a",diferencia:"#dc2626",enC3:"#7c3aed",completado:"#16a34a"};
  const stL={pendiente:"Pendiente",enCurso:"En curso",cerradoC1:"C1 cerrado",cerradoC2:"Completado",diferencia:"⚠️ Diferencia",enC3:"En C3",completado:"Completado"};
  return(<Section titulo="Programación de Conteos">
    <div style={{marginBottom:16}}><Btn c="#16a34a" onClick={()=>setModal(true)} disabled={!G.inventario||G.productos.length===0||saving}>+ Programar Conteo</Btn>{!G.inventario&&<span style={{marginLeft:12,fontSize:12,color:"#dc2626"}}>Primero crea un inventario.</span>}{G.inventario&&G.productos.length===0&&<span style={{marginLeft:12,fontSize:12,color:"#dc2626"}}>Primero carga productos.</span>}</div>
    {G.conteos.length===0?<div style={{...card,textAlign:"center",padding:36,color:"#64748b"}}>No hay conteos programados.</div>:(<div style={{...card,padding:0,overflow:"hidden"}}><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13,minWidth:700}}><thead><tr style={{background:"#0f172a",color:"white"}}>{["Nombre","Ubicación","C1","C2","Estado","Acciones"].map(h=><th key={h} style={{padding:"10px 12px",textAlign:"left",fontWeight:600,fontSize:11}}>{h}</th>)}</tr></thead><tbody>{G.conteos.map((c,i)=>(<tr key={c.id} style={{background:i%2?"#f8fafc":"white",borderBottom:"1px solid #f1f5f9"}}><td style={{padding:"10px 12px"}}><div style={{fontWeight:700}}>{c.nombre}</div>{c.obs&&<div style={{fontSize:11,color:"#64748b"}}>📝 {c.obs}</div>}</td><td style={{padding:"10px 12px",fontSize:12,color:"#64748b"}}>{c.locLabel}</td><td style={{padding:"10px 12px",fontWeight:600,color:"#2563eb"}}>{c.usuarioC1||"—"}</td><td style={{padding:"10px 12px",fontWeight:600,color:"#16a34a"}}>{c.usuarioC2||<span style={{color:"#d1d5db"}}>—</span>}</td><td style={{padding:"10px 12px"}}><Badge color={stC[c.estado]||"#6b7280"} small>{stL[c.estado]||c.estado}</Badge></td><td style={{padding:"10px 12px"}}><div style={{display:"flex",gap:6}}><button onClick={()=>{setModalMod(c);setModForm({obs:c.obs||"",usuarioC1:c.usuarioC1,usuarioC2:c.usuarioC2||""});}} style={{background:"#eff6ff",color:"#2563eb",border:"1px solid #bfdbfe",borderRadius:6,padding:"4px 10px",cursor:"pointer",fontWeight:700,fontSize:11}}>Modificar</button>{["cerradoC1","cerradoC2","completado","diferencia","enC3"].includes(c.estado)&&<button onClick={()=>reabrir(c.id)} style={{background:"#fef9c3",border:"1px solid #fde047",color:"#92400e",borderRadius:6,padding:"4px 10px",cursor:"pointer",fontWeight:700,fontSize:11}}>Reabrir</button>}</div></td></tr>))}</tbody></table></div></div>)}
    {modal&&(<Modal titulo="Programar Conteo" onClose={()=>setModal(false)}><Lbl>Nombre</Lbl><Inp value={form.nombre} onChange={e=>setForm(p=>({...p,nombre:e.target.value}))} placeholder="Ej: Conteo Bodega" style={{marginBottom:14}}/><Lbl>Localización</Lbl><Sel value={form.locId} onChange={e=>setForm(p=>({...p,locId:e.target.value}))} style={{marginBottom:14}}><option value="">Seleccionar…</option>{G.localizaciones.map(l=><option key={l.id} value={l.id}>{l.ubicacion} › {l.localizacion} › {l.nro}</option>)}</Sel><Lbl>Usuario C1 *</Lbl><Sel value={form.usuarioC1} onChange={e=>setForm(p=>({...p,usuarioC1:e.target.value}))} style={{marginBottom:14}}><option value="">Seleccionar…</option>{G.usuarios.filter(u=>u.activo).map(u=><option key={u.id}>{u.nombre}</option>)}</Sel>{G.inventario?.tipo==="2conteos"&&<><Lbl>Usuario C2</Lbl><Sel value={form.usuarioC2} onChange={e=>setForm(p=>({...p,usuarioC2:e.target.value}))} style={{marginBottom:14}}><option value="">Sin asignar…</option>{G.usuarios.filter(u=>u.activo).map(u=><option key={u.id}>{u.nombre}</option>)}</Sel></>}<Btn c="#16a34a" onClick={crear} full disabled={saving}>{saving?"Guardando...":"✓ Programar"}</Btn></Modal>)}
    {modalMod&&(<Modal titulo={`Modificar: ${modalMod.nombre}`} onClose={()=>setModalMod(null)}><Lbl>Observación</Lbl><Inp value={modForm.obs} onChange={e=>setModForm(p=>({...p,obs:e.target.value}))} style={{marginBottom:14}}/><Lbl>Usuario C1</Lbl><Sel value={modForm.usuarioC1} onChange={e=>setModForm(p=>({...p,usuarioC1:e.target.value}))} style={{marginBottom:14}}><option value="">Seleccionar…</option>{G.usuarios.filter(u=>u.activo).map(u=><option key={u.id}>{u.nombre}</option>)}</Sel>{modalMod.tipo==="2conteos"&&<><Lbl>Usuario C2</Lbl><Sel value={modForm.usuarioC2} onChange={e=>setModForm(p=>({...p,usuarioC2:e.target.value}))} style={{marginBottom:14}}><option value="">Sin asignar…</option>{G.usuarios.filter(u=>u.activo).map(u=><option key={u.id}>{u.nombre}</option>)}</Sel></>}<Btn c="#2563eb" onClick={guardarMod} full disabled={saving}>{saving?"Guardando...":"✓ Guardar"}</Btn></Modal>)}
  </Section>);
}

function VProcesos({G,rerender,showToast,db}){
  const caps=Object.values(G.capturas);const total=G.productos.length;
  const completos=G.conteos.filter(c=>["completado","cerradoC2"].includes(c.estado)).length;
  const pct=G.conteos.length?Math.round(completos/G.conteos.length*100):0;
  const getDifs=(c)=>{if(c.tipo!=="2conteos")return [];const difs=[];G.productos.forEach(p=>{const t1=caps.filter(x=>x.conteoId===c.id&&x.productoId===p.id&&x.ronda==="C1").reduce((s,x)=>s+x.cantidad,0);const t2=caps.filter(x=>x.conteoId===c.id&&x.productoId===p.id&&x.ronda==="C2").reduce((s,x)=>s+x.cantidad,0);if((t1>0||t2>0)&&t1!==t2)difs.push({...p,c1:t1,c2:t2,dif:t1-t2});});return difs;};
  const stC={pendiente:"#94a3b8",enCurso:"#2563eb",cerradoC1:"#d97706",cerradoC2:"#16a34a",diferencia:"#dc2626",enC3:"#7c3aed",completado:"#16a34a"};
  const asignarC3=async(id,u)=>{G.conteos=G.conteos.map(c=>c.id===id?{...c,usuarioC3:u,estado:"enC3"}:c);await db.upsertConteo(serConteo(G.conteos.find(c=>c.id===id),G.inventario?.id));rerender();showToast("C3 asignado ✓");};
  return(<div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}><h2 style={{margin:0,fontSize:20,fontWeight:700}}>Vista de Procesos</h2><div style={{fontSize:12,color:"#64748b"}}>{TODAY()}</div></div>
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:12,marginBottom:16}}>{[{l:"Total productos",v:total,c:"#2563eb"},{l:"Total conteos",v:G.conteos.length,c:"#475569"},{l:"Completados",v:completos,c:"#16a34a"},{l:"% Avance",v:pct+"%",c:"#0891b2"},{l:"Con diferencia",v:G.conteos.filter(c=>c.estado==="diferencia").length,c:"#dc2626"}].map(s=>(<div key={s.l} style={{...card,borderTop:`3px solid ${s.c}`,padding:"10px 14px"}}><div style={{fontSize:20,fontWeight:800,color:s.c}}>{s.v}</div><div style={{fontSize:11,color:"#64748b",marginTop:2}}>{s.l}</div></div>))}</div>
    <div style={{...card,marginBottom:16,padding:"12px 18px"}}><div style={{display:"flex",justifyContent:"space-between",fontSize:13,marginBottom:6}}><b>Avance del inventario</b><span style={{color:"#2563eb",fontWeight:700}}>{pct}% — {completos}/{G.conteos.length}</span></div><div style={{background:"#e2e8f0",borderRadius:99,height:12}}><div style={{width:pct+"%",background:"linear-gradient(90deg,#2563eb,#16a34a)",borderRadius:99,height:"100%",transition:"width 0.5s"}}/></div></div>
    {G.conteos.length===0?<div style={{...card,textAlign:"center",padding:36,color:"#64748b"}}>No hay conteos programados.</div>:(<div style={{...card,padding:0,overflow:"hidden"}}><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:12,minWidth:800}}><thead><tr style={{background:"#0f172a",color:"white"}}>{["Ubicación","N°","C1","Avance C1","C2","Avance C2","Difs","Estado","C3"].map(h=><th key={h} style={{padding:"9px 10px",textAlign:"left",fontWeight:600,fontSize:11}}>{h}</th>)}</tr></thead><tbody>{G.conteos.map((c,i)=>{const c1s=caps.filter(x=>x.conteoId===c.id&&x.ronda==="C1");const c2s=caps.filter(x=>x.conteoId===c.id&&x.ronda==="C2");const difs=getDifs(c);const p1=total?Math.round(new Set(c1s.map(x=>x.productoId)).size/total*100):0;const p2=total?Math.round(new Set(c2s.map(x=>x.productoId)).size/total*100):0;return(<tr key={c.id} style={{background:i%2?"#f8fafc":"white",borderBottom:"1px solid #e2e8f0"}}><td style={{padding:"10px 10px",fontWeight:700,color:"#1e40af"}}>{c.ubicacion}</td><td style={{padding:"10px 10px",fontWeight:600}}>{c.nro}</td><td style={{padding:"10px 10px",fontSize:11,fontWeight:600,color:"#2563eb"}}>{c.usuarioC1}</td><td style={{padding:"10px 10px"}}><div style={{display:"flex",alignItems:"center",gap:6}}><div style={{background:"#e2e8f0",borderRadius:99,height:6,width:70}}><div style={{width:p1+"%",background:"#2563eb",borderRadius:99,height:"100%"}}/></div><span style={{fontSize:10,color:"#64748b"}}>{p1}%</span></div></td><td style={{padding:"10px 10px",fontSize:11,fontWeight:600,color:"#16a34a"}}>{c.usuarioC2||<span style={{color:"#d1d5db"}}>—</span>}</td><td style={{padding:"10px 10px"}}>{c.usuarioC2?<div style={{display:"flex",alignItems:"center",gap:6}}><div style={{background:"#e2e8f0",borderRadius:99,height:6,width:70}}><div style={{width:p2+"%",background:"#16a34a",borderRadius:99,height:"100%"}}/></div><span style={{fontSize:10,color:"#64748b"}}>{p2}%</span></div>:<span style={{color:"#d1d5db",fontSize:11}}>—</span>}</td><td style={{padding:"10px 10px",textAlign:"center"}}>{difs.length>0?<span style={{fontWeight:800,color:"#dc2626"}}>{difs.length}</span>:<span style={{color:"#16a34a",fontWeight:700}}>0</span>}</td><td style={{padding:"10px 10px"}}><Badge color={stC[c.estado]||"#6b7280"} small>{c.estado}</Badge></td><td style={{padding:"10px 10px"}}>{c.estado==="diferencia"&&!c.usuarioC3&&(<select defaultValue="" onChange={e=>e.target.value&&asignarC3(c.id,e.target.value)} style={{...inp,width:"auto",fontSize:11,padding:"4px 8px",height:28}}><option value="" disabled>+ C3</option>{G.usuarios.filter(u=>u.activo).map(u=><option key={u.id}>{u.nombre}</option>)}</select>)}{c.usuarioC3&&<span style={{fontSize:11,color:"#7c3aed",fontWeight:700}}>{c.usuarioC3}</span>}</td></tr>);})}</tbody></table></div></div>)}
  </div>);
}

function VReportes({G,showToast,usuario}){
  const caps=Object.values(G.capturas);
  const expXLSX=(data,cols,fname,titulo)=>{const ws=XLSX.utils.aoa_to_sheet([[titulo],["Usuario: "+usuario.nombre+" | "+TODAY()],[],cols,...data]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,"Reporte");XLSX.writeFile(wb,fname);showToast("Exportado ✓");};
  const capFinal=G.productos.map(p=>{const misC=caps.filter(c=>c.productoId===p.id);if(!misC.length)return null;const s1=misC.filter(c=>c.ronda==="C1").reduce((s,c)=>s+c.cantidad,0);const s2=misC.filter(c=>c.ronda==="C2").reduce((s,c)=>s+c.cantidad,0);const s3=misC.filter(c=>c.ronda==="C3").reduce((s,c)=>s+c.cantidad,0);const f=s3||s2||s1;const last=misC[misC.length-1];const conteo=G.conteos.find(c=>c.id===last.conteoId);return{...p,ubicacion:conteo?.ubicacion||"",localizacion:conteo?.localizacion||"",nro:conteo?.nro||"",c1:s1||"",c2:s2||"",c3:s3||"",cantFinal:f,diferencia:f-p.saldo,valDif:(f-p.saldo)*p.costo,estado:last.estado||"",usuario:last.usuario};}).filter(Boolean);
  const difInv=capFinal.filter(c=>c.diferencia!==0);const contadoIds=new Set(caps.map(c=>c.productoId));const sinConteo=G.productos.filter(p=>!contadoIds.has(p.id));
  return(<Section titulo="Reportes"><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(230px,1fr))",gap:16}}>{[{icon:"⚪",titulo:"Sin Conteo",desc:"No inventariados",v:sinConteo.length,c:"#d97706",fn:()=>expXLSX(sinConteo.map(p=>[p.codigo,p.nombre,p.referencia,p.categoria,p.saldo,p.costo]),["CODIGO","NOMBRE","REFERENCIA","CATEGORIA","SALDO","COSTO"],"sin_conteo.xlsx","SIN CONTEOS"),d:sinConteo.length===0},{icon:"⚖️",titulo:"Diferencia Inventario",desc:"Físico vs Sistema",v:difInv.length,c:"#2563eb",fn:()=>expXLSX(difInv.map(c=>[c.codigo,c.nombre,c.referencia,c.costo||0,c.saldo,c.cantFinal,c.diferencia,Math.round(c.valDif),c.categoria||""]),["CODIGO","NOMBRE","REFERENCIA","COSTO","SALDO","CANTIDAD","DIFERENCIA","VALOR_DIF","CATEGORIA"],"diferencia.xlsx","DIFERENCIA"),d:difInv.length===0},{icon:"🔧",titulo:"Ajuste",desc:"Código · Cantidad · Fecha",v:capFinal.length,c:"#16a34a",fn:()=>expXLSX(capFinal.map(c=>[c.codigo,c.cantFinal,c.saldo,TODAY()]),["CODIGO","CANTIDAD","SALDO","FECH_CORTE"],"ajuste.xlsx","AJUSTE"),d:capFinal.length===0},{icon:"📄",titulo:"Reporte de Captura",desc:"C1·C2·C3 en columnas",v:capFinal.length,c:"#7c3aed",fn:()=>expXLSX(capFinal.map(c=>[c.ean,c.codigo,c.nombre,c.referencia,c.categoria,c.ubicacion,c.localizacion,c.nro,c.c1||"",c.c2||"",c.c3||"",c.cantFinal,c.costo,c.estado,c.usuario]),["EAN","CODIGO","NOMBRE","REFERENCIA","CATEGORIA","UBICACION","LOCALIZACION","N_LOCAL","C1","C2","C3","FINAL","COSTO","ESTADO","USUARIO"],"captura.xlsx","CAPTURA"),d:capFinal.length===0}].map((r,i)=>(<div key={i} style={card}><div style={{fontSize:26,marginBottom:6}}>{r.icon}</div><h3 style={{margin:"0 0 4px",fontSize:14,fontWeight:700}}>{r.titulo}</h3><p style={{fontSize:12,color:"#64748b",margin:"0 0 12px"}}>{r.desc}</p><div style={{background:r.c+"22",borderRadius:8,padding:8,fontSize:24,fontWeight:800,color:r.c,textAlign:"center",marginBottom:12}}>{r.v}</div><Btn c={r.c} onClick={r.fn} disabled={r.d} full>⬇ Exportar Excel</Btn></div>))}</div></Section>);
}

function VUsuarios({G,rerender,showToast,db}){
  const [modal,setModal]=useState(false);const [form,setForm]=useState({nombre:"",pass:"",rol:"capturador",correo:"",telefono:"",editId:null});const [saving,setSaving]=useState(false);const [delU,setDelU]=useState(null);
  const genPass=(n,t)=>{const a=(n||"").toUpperCase().replace(/[^A-Z]/g,"").substring(0,3).padEnd(3,"X");const b=(t||"").replace(/\D/g,"");return a+(b.length>=4?b.slice(-4):"1234");};
  const guardar=async()=>{if(!form.nombre.trim()||!form.pass.trim())return showToast("Completa nombre y contraseña","err");setSaving(true);if(form.editId){G.usuarios=G.usuarios.map(u=>u.id===form.editId?{...u,...form,nombre:form.nombre.toUpperCase(),id:u.id}:u);await db.upsertUsuario(G.usuarios.find(u=>u.id===form.editId));}else{if(G.usuarios.find(u=>u.nombre===form.nombre.toUpperCase())){setSaving(false);return showToast("Ya existe","err");}const nuevo={id:ID(),nombre:form.nombre.toUpperCase(),pass:form.pass,rol:form.rol,correo:form.correo,telefono:form.telefono,activo:true,creado:TODAY()};await db.upsertUsuario(nuevo);G.usuarios.push(nuevo);}setModal(false);setForm({nombre:"",pass:"",rol:"capturador",correo:"",telefono:"",editId:null});setSaving(false);rerender();showToast(form.editId?"Actualizado ✓":"Creado ✓");};
  const eliminar=async(u)=>{await db.deleteUsuario(u.id);G.usuarios=G.usuarios.filter(x=>x.id!==u.id);setDelU(null);rerender();showToast("Eliminado ✓","warn");};
  const copiar=(u)=>{const msg=`Hola ${u.nombre}! Datos para TOMFIC:\n🔗 https://tomfic.vercel.app\n👤 Usuario: ${u.nombre}\n🔑 Contraseña: ${u.pass}`;navigator.clipboard?.writeText(msg).then(()=>showToast("Copiado ✓")).catch(()=>showToast("No se pudo copiar","err"));};
  return(<Section titulo="Gestión de Usuarios">
    <div style={{marginBottom:16}}><Btn c="#16a34a" onClick={()=>{setForm({nombre:"",pass:"",rol:"capturador",correo:"",telefono:"",editId:null});setModal(true);}}>+ Crear Usuario</Btn></div>
    <div style={{...card,padding:0,overflow:"hidden"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}><thead><tr style={{background:"#0f172a",color:"white"}}>{["Usuario","Contraseña","Rol","Estado","Acciones"].map(h=><th key={h} style={{padding:"10px 14px",textAlign:"left",fontWeight:600}}>{h}</th>)}</tr></thead><tbody>{G.usuarios.map((u,i)=>(<tr key={u.id} style={{background:i%2?"#f8fafc":"white",borderBottom:"1px solid #f1f5f9"}}><td style={{padding:"9px 14px"}}><b>{u.nombre}</b></td><td style={{padding:"9px 14px",fontFamily:"monospace",fontSize:12,color:"#64748b"}}>{u.pass}</td><td style={{padding:"9px 14px"}}><Badge color={u.rol==="admin"?"#2563eb":"#16a34a"}>{u.rol==="admin"?"ADMIN":"CAPTURADOR"}</Badge></td><td style={{padding:"9px 14px"}}><Badge color={u.activo?"#16a34a":"#dc2626"}>{u.activo?"ACTIVO":"INACTIVO"}</Badge></td><td style={{padding:"9px 14px"}}><div style={{display:"flex",gap:6,flexWrap:"wrap"}}><Btn c="#2563eb" small onClick={()=>{setForm({nombre:u.nombre,pass:u.pass,rol:u.rol,correo:u.correo||"",telefono:u.telefono||"",editId:u.id});setModal(true);}}>Editar</Btn><button onClick={()=>copiar(u)} style={{background:"#25d366",color:"white",border:"none",borderRadius:6,padding:"4px 10px",cursor:"pointer",fontWeight:700,fontSize:11}}>📋 Copiar</button>{u.nombre!=="ADMIN"&&<Btn c={u.activo?"#d97706":"#16a34a"} small onClick={async()=>{G.usuarios=G.usuarios.map(x=>x.id===u.id?{...x,activo:!x.activo}:x);await db.upsertUsuario(G.usuarios.find(x=>x.id===u.id));rerender();}}>{u.activo?"Desactivar":"Activar"}</Btn>}{u.nombre!=="ADMIN"&&<button onClick={()=>setDelU(u)} style={{background:"#fef2f2",color:"#dc2626",border:"1px solid #fecaca",borderRadius:6,padding:"4px 10px",cursor:"pointer",fontWeight:700,fontSize:11}}>Eliminar</button>}</div></td></tr>))}</tbody></table></div>
    {modal&&(<Modal titulo={form.editId?"Editar Usuario":"Crear Usuario"} onClose={()=>setModal(false)}><Lbl>Nombre</Lbl><Inp value={form.nombre} onChange={e=>{const n=e.target.value.toUpperCase();setForm(p=>({...p,nombre:n,...(!p.editId?{pass:genPass(n,p.telefono)}:{})}));}} disabled={!!form.editId} style={{marginBottom:14}}/><Lbl>Contraseña</Lbl><Inp value={form.pass} onChange={e=>setForm(p=>({...p,pass:e.target.value}))} style={{marginBottom:14}}/><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:14}}><div><Lbl>Correo</Lbl><Inp value={form.correo} onChange={e=>setForm(p=>({...p,correo:e.target.value}))} placeholder="correo@ejemplo.com"/></div><div><Lbl>Teléfono</Lbl><Inp value={form.telefono} onChange={e=>{const t=e.target.value;setForm(p=>({...p,telefono:t,...(!p.editId?{pass:genPass(p.nombre,t)}:{})}));}} placeholder="3001234567"/></div></div><Lbl>Rol</Lbl><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:16}}>{[["capturador","Capturador"],["admin","Administrador"]].map(([v,t])=>(<div key={v} onClick={()=>setForm(p=>({...p,rol:v}))} style={{border:`2px solid ${form.rol===v?"#2563eb":"#e2e8f0"}`,borderRadius:10,padding:12,cursor:"pointer",background:form.rol===v?"#eff6ff":"white"}}><div style={{fontWeight:700,color:form.rol===v?"#2563eb":"#0f172a",fontSize:13}}>{t}</div></div>))}</div><Btn c="#2563eb" onClick={guardar} full disabled={saving}>{saving?"Guardando...":form.editId?"Actualizar":"Crear"}</Btn></Modal>)}
    {delU&&(<Modal titulo="Eliminar Usuario" onClose={()=>setDelU(null)}><div style={{background:"#fef2f2",border:"1px solid #fecaca",borderRadius:10,padding:16,marginBottom:20,fontSize:14,color:"#dc2626"}}>¿Eliminar a <b>{delU.nombre}</b>?</div><div style={{display:"flex",gap:10}}><Btn c="#dc2626" onClick={()=>eliminar(delU)} full>Sí, eliminar</Btn><Btn c="#64748b" onClick={()=>setDelU(null)} full>Cancelar</Btn></div></Modal>)}
  </Section>);
}

function VHistorial({G,showToast}){
  const [invSel,setInvSel]=useState(null);
  const fmt=(n)=>"$"+Math.round(n).toLocaleString("es-CO");
  const expXLSX=(data,cols,fname,titulo)=>{const ws=XLSX.utils.aoa_to_sheet([[titulo],[TODAY()],[],cols,...data]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,"Historial");XLSX.writeFile(wb,fname);showToast("Exportado ✓");};
  const getSt=(inv)=>{const caps=Object.values(inv.capturas||{});const prods=inv.productos||[];const pp={};caps.forEach(c=>{if(!pp[c.productoId])pp[c.productoId]={...c,totalC1:0,totalC2:0,totalC3:0};if(c.ronda==="C1")pp[c.productoId].totalC1+=c.cantidad;if(c.ronda==="C2")pp[c.productoId].totalC2+=c.cantidad;if(c.ronda==="C3")pp[c.productoId].totalC3+=c.cantidad;});const resumen=Object.values(pp).map(r=>({...r,cantFinal:r.totalC3||r.totalC2||r.totalC1}));const totalFisico=resumen.reduce((s,r)=>s+(r.cantFinal*(r.costo||0)),0);const totalSistema=prods.reduce((s,p)=>s+(p.saldo*(p.costo||0)),0);const conDif=resumen.filter(r=>{const p=prods.find(x=>x.id===r.productoId);return p&&r.cantFinal!==p.saldo;});return{totalFisico,totalSistema,ajuste:totalFisico-totalSistema,conDif,resumen,contados:resumen.length,totalProductos:prods.length};};
  if(invSel){const st=getSt(invSel);return(<div><div style={{display:"flex",alignItems:"center",gap:12,marginBottom:16}}><button onClick={()=>setInvSel(null)} style={{background:"#f1f5f9",border:"none",borderRadius:8,padding:"7px 14px",cursor:"pointer",fontWeight:600,fontSize:13}}>← Historial</button><h2 style={{margin:0,fontSize:20,fontWeight:700}}>{invSel.nombre}</h2></div><div style={{fontSize:12,color:"#64748b",marginBottom:16}}>📅 {invSel.apertura} → {invSel.cierre} · Por: {invSel.usuarioApertura}</div><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:12,marginBottom:20}}>{[{l:"💰 Valor físico",v:fmt(st.totalFisico),c:"#16a34a"},{l:"📊 Valor sistema",v:fmt(st.totalSistema),c:"#2563eb"},{l:"⚖️ Ajuste",v:(st.ajuste>=0?"+":"")+fmt(st.ajuste),c:st.ajuste>=0?"#16a34a":"#dc2626"},{l:"📦 Contados",v:`${st.contados}/${st.totalProductos}`,c:"#0891b2"},{l:"⚠️ Con diferencia",v:st.conDif.length,c:"#ef4444"}].map((s,i)=>(<div key={i} style={{...card,borderTop:`3px solid ${s.c}`,padding:"12px 16px"}}><div style={{fontSize:typeof s.v==="string"&&s.v.length>8?14:20,fontWeight:800,color:s.c}}>{s.v}</div><div style={{fontSize:11,color:"#64748b",marginTop:3}}>{s.l}</div></div>))}</div><div style={{display:"flex",gap:10,flexWrap:"wrap"}}><Btn c="#2563eb" onClick={()=>expXLSX(st.resumen.map(r=>[r.ean||"",r.codigo,r.nombre,r.referencia,r.totalC1||"",r.totalC2||"",r.totalC3||"",r.cantFinal,r.estado||"",r.usuario]),["EAN","CODIGO","NOMBRE","REFERENCIA","C1","C2","C3","FINAL","ESTADO","USUARIO"],`captura_${invSel.nombre?.replace(/ /g,"_")}.xlsx`,`CAPTURA ${invSel.nombre}`)}>⬇ Excel capturas</Btn><Btn c="#16a34a" onClick={()=>expXLSX(st.conDif.map(r=>{const p=(invSel.productos||[]).find(x=>x.id===r.productoId);const dif=r.cantFinal-(p?.saldo||0);return[r.codigo,r.nombre,p?.saldo||0,r.cantFinal,dif,Math.round(dif*(p?.costo||0))];}),["CODIGO","NOMBRE","SALDO","FISICO","DIFERENCIA","VALOR_DIF"],`ajuste_${invSel.nombre?.replace(/ /g,"_")}.xlsx`,`AJUSTE ${invSel.nombre}`)}>⬇ Excel ajuste</Btn></div></div>);}
  return(<div><h2 style={{margin:"0 0 20px",fontSize:20,fontWeight:700}}>Historial de Inventarios</h2>{G.historial.length===0?(<div style={{...card,textAlign:"center",padding:40,color:"#64748b"}}>No hay inventarios cerrados aún.</div>):(<div style={{display:"flex",flexDirection:"column",gap:12}}>{G.historial.map((h,i)=>{const st=getSt(h);return(<div key={i} style={{...card,cursor:"pointer",borderLeft:"4px solid #2563eb"}} onClick={()=>setInvSel(h)}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}><div><div style={{fontWeight:700,fontSize:15}}>{h.nombre}</div><div style={{fontSize:12,color:"#64748b",marginTop:3}}>{h.apertura} → {h.cierre}</div><div style={{display:"flex",gap:16,marginTop:8}}><span style={{fontSize:12,color:"#16a34a",fontWeight:700}}>💰 {fmt(st.totalFisico)}</span><span style={{fontSize:12,color:st.ajuste>=0?"#16a34a":"#dc2626",fontWeight:700}}>⚖️ {(st.ajuste>=0?"+":"")+fmt(st.ajuste)}</span><span style={{fontSize:12,color:"#64748b"}}>{st.contados}/{st.totalProductos} productos</span></div></div><span style={{fontSize:12,color:"#2563eb",fontWeight:600}}>Ver detalle →</span></div></div>);})}</div>)}</div>);
}

function ModCapturador({usuario,setUsuario,G,rerender,recargar,showToast,db}){
  const [conteoActivo,setConteoActivo]=useState(null);
  const [scanInput,setScanInput]=useState("");
  const [productoActivo,setProductoActivo]=useState(null);
  const [form,setForm]=useState({unidades:"",embalaje:"",cajas:"",estado:"BUENO",obs:""});
  const [c3Vals,setC3Vals]=useState({});
  const [notFound,setNotFound]=useState(false);
  const [modalCerrar,setModalCerrar]=useState(false);
  const [busqueda,setBusqueda]=useState("");
  const [saving,setSaving]=useState(false);
  const scanRef=useRef(null);const unidadesRef=useRef(null);

  const misConteos=G.conteos.filter(c=>c.usuarioC1===usuario.nombre||c.usuarioC2===usuario.nombre||c.usuarioC3===usuario.nombre);
  const miConteo=G.conteos.find(c=>c.id===conteoActivo)||null;
  const getMiRonda=(c)=>{if(!c)return null;if(c.usuarioC3===usuario.nombre&&c.estado==="enC3")return "C3";if(c.usuarioC2===usuario.nombre)return "C2";return "C1";};
  const miRonda=getMiRonda(miConteo);
  const getRC=(c)=>c?.rondasCerradas||[];
  const miRondaCerrada=(c)=>{const r=getMiRonda(c);return getRC(c).includes(r)||(r==="C3"&&c?.estado==="completado");};
  const puedoCapturar=(c)=>{if(!c)return false;if(miRondaCerrada(c))return false;const r=getMiRonda(c);if(r==="C3")return c.estado==="enC3";return true;};
  const soyPrincipal=(c)=>{if(!c)return false;const r=getMiRonda(c);if(r==="C1")return c.usuarioC1===usuario.nombre;if(r==="C2")return c.usuarioC2===usuario.nombre;return c.usuarioC3===usuario.nombre;};

  const prodsC3=miConteo?G.productos.filter(p=>{const t1=Object.values(G.capturas).filter(c=>c.conteoId===miConteo.id&&c.productoId===p.id&&c.ronda==="C1").reduce((s,c)=>s+c.cantidad,0);const t2=Object.values(G.capturas).filter(c=>c.conteoId===miConteo.id&&c.productoId===p.id&&c.ronda==="C2").reduce((s,c)=>s+c.cantidad,0);return(t1>0||t2>0)&&t1!==t2;}):[];
  const prods=miConteo?(miRonda==="C3"?prodsC3:G.productos):[];
  const getCaps=(cid,r,pid)=>Object.values(G.capturas).filter(c=>c.conteoId===cid&&c.ronda===r&&c.productoId===pid);
  const getTotal=(cid,r,pid)=>getCaps(cid,r,pid).reduce((s,c)=>s+c.cantidad,0);
  const capsReal=miConteo?prods.map(p=>({p,total:getTotal(miConteo.id,miRonda,p.id),caps:getCaps(miConteo.id,miRonda,p.id)})).filter(x=>x.caps.length>0):[];

  const buscarProd=(q)=>{const s=q.trim().toLowerCase();return prods.find(p=>p.ean===s||p.ean===q.trim()||p.codigo.toLowerCase()===s||p.nombre.toLowerCase().includes(s))||null;};
  const handleScan=(e)=>{if(e.key!=="Enter")return;const p=buscarProd(scanInput);setNotFound(!p);if(p){setProductoActivo(p);setForm({unidades:"",embalaje:"",cajas:"",estado:"BUENO",obs:""});setTimeout(()=>unidadesRef.current?.focus(),80);}setScanInput("");};
  const calcTotal=(f)=>(parseFloat(f.unidades)||0)+(parseFloat(f.cajas)||0)*(parseFloat(f.embalaje)||1);

  const persistConteo=async(c)=>{await db.upsertConteo(serConteo(c,G.inventario?.id));};

  const guardar=async()=>{
    if(!productoActivo||!miConteo||!miRonda)return;
    const total=calcTotal(form);
    if(miRonda!=="C3"&&total<=0)return showToast("Ingresa al menos las unidades","err");
    setSaving(true);
    if(miConteo.estado==="pendiente")G.conteos=G.conteos.map(c=>c.id===miConteo.id?{...c,estado:"enCurso"}:c);
    const key=`${miConteo.id}_${productoActivo.id}_${miRonda}_${ID()}`;
    const captura={conteoId:miConteo.id,productoId:productoActivo.id,ronda:miRonda,ean:productoActivo.ean,codigo:productoActivo.codigo,nombre:productoActivo.nombre,referencia:productoActivo.referencia,categoria:productoActivo.categoria,subcategoria:productoActivo.subcategoria,subgrupo:productoActivo.subgrupo,saldo:productoActivo.saldo,costo:productoActivo.costo,proveedor:productoActivo.proveedor,nit:productoActivo.nit,cantidad:total,unidades:parseFloat(form.unidades)||0,cajas:parseFloat(form.cajas)||0,embalaje:parseFloat(form.embalaje)||0,estado:form.estado,obs:form.obs,usuario:usuario.nombre,fecha:TODAY(),hora:HOUR()};
    G.capturas[key]=captura;
    const c=G.conteos.find(x=>x.id===miConteo.id);if(c){c.capturas=c.capturas||{};c.capturas[key]=captura;await persistConteo(c);}
    setSaving(false);rerender();showToast(`✓ ${productoActivo.nombre} — ${total} und`);
    setProductoActivo(null);setForm({unidades:"",embalaje:"",cajas:"",estado:"BUENO",obs:""});setTimeout(()=>scanRef.current?.focus(),80);
  };

  const guardarC3Fila=async(p,val)=>{
    const cantidad=parseFloat(val);if(isNaN(cantidad)||cantidad<0)return showToast("Valor inválido","err");
    setSaving(true);
    if(miConteo.estado==="pendiente")G.conteos=G.conteos.map(c=>c.id===miConteo.id?{...c,estado:"enCurso"}:c);
    const key=`${miConteo.id}_${p.id}_C3_${ID()}`;
    const captura={conteoId:miConteo.id,productoId:p.id,ronda:"C3",ean:p.ean,codigo:p.codigo,nombre:p.nombre,referencia:p.referencia,categoria:p.categoria,subcategoria:p.subcategoria,subgrupo:p.subgrupo,saldo:p.saldo,costo:p.costo,proveedor:p.proveedor,nit:p.nit,cantidad,estado:"BUENO",obs:"",usuario:usuario.nombre,fecha:TODAY(),hora:HOUR()};
    G.capturas[key]=captura;const c=G.conteos.find(x=>x.id===miConteo.id);if(c){c.capturas=c.capturas||{};c.capturas[key]=captura;await persistConteo(c);}
    setC3Vals(prev=>({...prev,[p.id]:""}));setSaving(false);rerender();showToast(`✓ ${p.nombre} — ${cantidad}`);
  };

  const cerrarConteo=async()=>{
    if(!miConteo||!miRonda||!soyPrincipal(miConteo))return;
    setSaving(true);
    const rondasCerradas=[...getRC(miConteo),miRonda];let nuevoEstado=miConteo.estado;
    const hayDif=()=>G.productos.some(p=>{const t1=Object.values(G.capturas).filter(c=>c.conteoId===miConteo.id&&c.productoId===p.id&&c.ronda==="C1").reduce((s,c)=>s+c.cantidad,0);const t2=Object.values(G.capturas).filter(c=>c.conteoId===miConteo.id&&c.productoId===p.id&&c.ronda==="C2").reduce((s,c)=>s+c.cantidad,0);return(t1>0||t2>0)&&t1!==t2;});
    if(miRonda==="C1"){nuevoEstado=rondasCerradas.includes("C2")?(hayDif()?"diferencia":"completado"):"cerradoC1";}
    else if(miRonda==="C2"){nuevoEstado=rondasCerradas.includes("C1")?(hayDif()?"diferencia":"completado"):"cerradoC2";}
    else if(miRonda==="C3")nuevoEstado="completado";
    G.conteos=G.conteos.map(c=>c.id===miConteo.id?{...c,estado:nuevoEstado,rondasCerradas}:c);
    await persistConteo(G.conteos.find(c=>c.id===miConteo.id));
    setModalCerrar(false);setConteoActivo(null);setSaving(false);rerender();showToast("Conteo terminado ✓");
  };

  const rcol={C1:"#2563eb",C2:"#16a34a",C3:"#7c3aed"};const rlbl={C1:"CONTEO 1",C2:"CONTEO 2",C3:"CONTEO 3"};

  if(!conteoActivo||!miConteo){
    const activos=misConteos.filter(c=>!miRondaCerrada(c));const cerrados=misConteos.filter(c=>miRondaCerrada(c));
    return(<div style={{minHeight:"100vh",background:"#f1f5f9",fontFamily:"system-ui,sans-serif"}}>
      <div style={{background:"#0f172a",color:"white",padding:"0 16px",display:"flex",alignItems:"center",justifyContent:"space-between",height:52,position:"sticky",top:0,zIndex:100}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}><span style={{fontSize:20}}>📦</span><span style={{fontWeight:800,fontSize:15}}>TOMFIC</span>{G.inventario&&<span style={{background:"#16a34a",fontSize:10,padding:"2px 10px",borderRadius:20,fontWeight:700}}>● {G.inventario.nombre}</span>}</div>
        <div style={{display:"flex",gap:10,alignItems:"center"}}><button onClick={recargar} style={{background:"transparent",border:"1px solid #334155",color:"#94a3b8",padding:"4px 10px",borderRadius:6,fontSize:11,cursor:"pointer"}}>🔄</button><span style={{fontSize:11,color:"#94a3b8"}}>👤 {usuario.nombre}</span><button onClick={()=>setUsuario(null)} style={{background:"transparent",border:"1px solid #334155",color:"#94a3b8",padding:"4px 10px",borderRadius:6,fontSize:11,cursor:"pointer"}}>Salir</button></div>
      </div>
      <div style={{maxWidth:700,margin:"0 auto",padding:"20px 14px"}}>
        <h2 style={{margin:"0 0 16px",fontSize:20,fontWeight:700}}>Mis conteos asignados</h2>
        <div style={{marginBottom:20}}><div style={{fontSize:11,fontWeight:700,color:"#374151",textTransform:"uppercase",letterSpacing:1,marginBottom:10}}>Activos / Pendientes</div>
          {activos.length===0?(<div style={{...card,padding:"20px 18px",color:"#64748b",textAlign:"center"}}><div style={{fontSize:32,marginBottom:8}}>📭</div><div style={{fontSize:14,fontWeight:600}}>No tienes conteos asignados</div></div>):(<div style={{...card,padding:0,overflow:"hidden"}}>{activos.map((c,i)=>{const r=getMiRonda(c);const caps=Object.values(G.capturas).filter(x=>x.conteoId===c.id&&x.ronda===r);const puede=puedoCapturar(c);return(<div key={c.id} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"12px 16px",borderBottom:i<activos.length-1?"1px solid #f1f5f9":"none",gap:12}}><div style={{flex:1,minWidth:0}}><div style={{fontWeight:700,fontSize:14,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{c.nombre}</div><div style={{fontSize:11,color:"#64748b",marginTop:2}}>📍 {c.locLabel}</div><div style={{display:"flex",gap:6,marginTop:6}}><Badge color={rcol[r]} small>{rlbl[r]}</Badge>{caps.length>0&&<Badge color="#64748b" small>{new Set(caps.map(x=>x.productoId)).size} capturados</Badge>}</div></div><button onClick={()=>{if(puede)setConteoActivo(c.id);}} style={{padding:"8px 16px",background:puede?rcol[r]:"#e2e8f0",color:puede?"white":"#94a3b8",border:"none",borderRadius:8,cursor:puede?"pointer":"not-allowed",fontWeight:700,fontSize:13,flexShrink:0}}>{caps.length>0?"Continuar":"Iniciar"}</button></div>);})}</div>)}
        </div>
        {cerrados.length>0&&(<div><div style={{fontSize:11,fontWeight:700,color:"#374151",textTransform:"uppercase",letterSpacing:1,marginBottom:10}}>Completados</div><div style={{...card,padding:0,overflow:"hidden"}}>{cerrados.map((c,i)=>{const r=getMiRonda(c);return(<div key={c.id} style={{display:"flex",alignItems:"center",padding:"10px 16px",borderBottom:i<cerrados.length-1?"1px solid #f1f5f9":"none",opacity:0.7}}><div><div style={{fontWeight:600,fontSize:13,color:"#64748b"}}>{c.nombre}</div><div style={{display:"flex",gap:6,marginTop:4}}><Badge color="#64748b" small>{rlbl[r]}</Badge><Badge color="#16a34a" small>🔒 Cerrado</Badge></div></div></div>);})}</div></div>)}
      </div>
    </div>);
  }

  const total=calcTotal(form);
  return(<div style={{minHeight:"100vh",background:"#f1f5f9",fontFamily:"system-ui,sans-serif"}}>
    <div style={{background:"#0f172a",color:"white",padding:"0 16px",display:"flex",alignItems:"center",justifyContent:"space-between",height:52,position:"sticky",top:0,zIndex:100}}>
      <div style={{display:"flex",alignItems:"center",gap:10}}><button onClick={()=>{setConteoActivo(null);setProductoActivo(null);setScanInput("");setBusqueda("");}} style={{background:"transparent",border:"1px solid #334155",color:"#94a3b8",padding:"4px 10px",borderRadius:6,fontSize:11,cursor:"pointer"}}>← Mis conteos</button><span style={{fontWeight:800,fontSize:15}}>TOMFIC</span><span style={{background:rcol[miRonda],fontSize:10,padding:"2px 10px",borderRadius:20,fontWeight:700}}>{rlbl[miRonda]}</span></div>
      <div style={{display:"flex",gap:10,alignItems:"center"}}><span style={{fontSize:11,color:"#94a3b8"}}>👤 {usuario.nombre}</span>{soyPrincipal(miConteo)&&<button onClick={()=>setModalCerrar(true)} style={{background:"#dc2626",color:"white",border:"none",padding:"6px 14px",borderRadius:8,cursor:"pointer",fontSize:12,fontWeight:700}}>Terminar</button>}<button onClick={()=>setUsuario(null)} style={{background:"transparent",border:"1px solid #334155",color:"#94a3b8",padding:"4px 10px",borderRadius:6,fontSize:11,cursor:"pointer"}}>Salir</button></div>
    </div>
    <div style={{padding:"12px 14px",maxWidth:1000,margin:"0 auto"}}>
      <div style={{background:"white",borderRadius:10,padding:"12px 16px",marginBottom:10,boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}><div style={{fontWeight:700,fontSize:14}}>{miConteo.nombre}</div><div style={{fontSize:12,color:"#64748b",marginTop:2}}>📍 {miConteo.locLabel}</div>{miRonda==="C3"&&<div style={{marginTop:6,background:"#faf5ff",borderRadius:6,padding:"4px 10px",fontSize:12,color:"#7c3aed",fontWeight:600,display:"inline-block"}}>Solo productos con diferencia — {prodsC3.length}</div>}</div>
      {miRonda==="C3"&&prodsC3.length>0&&(<div style={{background:"white",borderRadius:10,overflow:"hidden",boxShadow:"0 1px 4px rgba(0,0,0,0.06)",marginBottom:10}}><div style={{padding:"10px 16px",background:"#faf5ff",borderBottom:"1px solid #e9d5ff",display:"flex",justifyContent:"space-between",alignItems:"center"}}><span style={{fontWeight:700,fontSize:13,color:"#7c3aed"}}>Productos con diferencia</span><span style={{fontSize:12,color:"#7c3aed"}}>{prodsC3.length} productos</span></div><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead><tr style={{background:"#f3e8ff"}}>{["Código","Nombre","C1","C2","Dif","Conteo 3",""].map(h=><th key={h} style={{padding:"8px 10px",textAlign:"left",fontWeight:700,color:"#7c3aed"}}>{h}</th>)}</tr></thead><tbody>{prodsC3.map((p,i)=>{const t1=Object.values(G.capturas).filter(c=>c.conteoId===miConteo.id&&c.productoId===p.id&&c.ronda==="C1").reduce((s,c)=>s+c.cantidad,0);const t2=Object.values(G.capturas).filter(c=>c.conteoId===miConteo.id&&c.productoId===p.id&&c.ronda==="C2").reduce((s,c)=>s+c.cantidad,0);const t3=getTotal(miConteo.id,"C3",p.id);const ya=t3>0||Object.values(G.capturas).some(c=>c.conteoId===miConteo.id&&c.productoId===p.id&&c.ronda==="C3"&&c.cantidad===0);return(<tr key={p.id} style={{background:ya?"#f0fdf4":i%2?"#faf5ff":"white",borderBottom:"1px solid #f3e8ff"}}><td style={{padding:"8px 10px",fontFamily:"monospace",color:"#7c3aed",fontWeight:700}}>{p.codigo}</td><td style={{padding:"8px 10px",fontWeight:600}}>{p.nombre}</td><td style={{padding:"8px 10px",textAlign:"center",fontWeight:700,color:"#2563eb"}}>{t1}</td><td style={{padding:"8px 10px",textAlign:"center",fontWeight:700,color:"#16a34a"}}>{t2}</td><td style={{padding:"8px 10px",textAlign:"center",fontWeight:700,color:"#dc2626"}}>{t1-t2>0?"+":""}{t1-t2}</td><td style={{padding:"6px 8px"}}>{ya?<span style={{fontWeight:800,fontSize:14,color:"#16a34a"}}>{t3} ✓</span>:(<input type="number" min="0" value={c3Vals[p.id]??""} onChange={e=>setC3Vals(prev=>({...prev,[p.id]:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter"&&(c3Vals[p.id]!==undefined&&c3Vals[p.id]!==""))guardarC3Fila(p,c3Vals[p.id]);}} placeholder="0" style={{...inp,width:80,padding:"6px 8px",fontSize:15,fontWeight:700,textAlign:"center",border:"2px solid #7c3aed"}}/>)}</td><td style={{padding:"6px 8px"}}>{!ya&&<button onClick={()=>{const v=c3Vals[p.id];if(v!==undefined&&v!=="")guardarC3Fila(p,v);}} disabled={c3Vals[p.id]===undefined||c3Vals[p.id]===""} style={{background:c3Vals[p.id]!==undefined&&c3Vals[p.id]!==""?"#7c3aed":"#e2e8f0",color:c3Vals[p.id]!==undefined&&c3Vals[p.id]!==""?"white":"#94a3b8",border:"none",borderRadius:6,padding:"5px 12px",cursor:"pointer",fontWeight:700,fontSize:11}}>Guardar</button>}</td></tr>);})}</tbody></table>{soyPrincipal(miConteo)&&<div style={{padding:"10px 16px",background:"#f8fafc",borderTop:"1px solid #e2e8f0",display:"flex",justifyContent:"flex-end"}}><button onClick={()=>setModalCerrar(true)} style={{background:"#dc2626",color:"white",border:"none",borderRadius:8,padding:"8px 20px",cursor:"pointer",fontWeight:700,fontSize:13}}>TERMINAR CONTEO</button></div>}</div>)}

      <div style={{background:"white",borderRadius:10,padding:"12px 14px",marginBottom:10,boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}><div><div style={{fontSize:11,fontWeight:700,color:"#374151",marginBottom:5}}>CÓDIGO (EAN / INTERNO)</div><div style={{display:"flex",gap:8}}><input ref={scanRef} value={scanInput} onChange={e=>setScanInput(e.target.value)} onKeyDown={handleScan} placeholder="Escanee o escriba y Enter…" style={{...inp,flex:1,border:`2px solid ${rcol[miRonda]}`}} autoFocus/><button onClick={()=>handleScan({key:"Enter"})} style={{padding:"9px 14px",background:rcol[miRonda],color:"white",border:"none",borderRadius:8,cursor:"pointer",fontWeight:700,fontSize:15}}>↵</button></div>{notFound&&<div style={{marginTop:6,color:"#dc2626",fontSize:12,fontWeight:600}}>⚠️ Código no encontrado</div>}</div><div style={{position:"relative"}}><div style={{fontSize:11,fontWeight:700,color:"#374151",marginBottom:5}}>BUSCAR EN LA LISTA</div><input value={busqueda} onChange={e=>{setBusqueda(e.target.value);setProductoActivo(null);}} placeholder="Nombre, código…" style={{...inp,border:`1.5px solid ${busqueda?"#2563eb":"#e2e8f0"}`}} autoComplete="off"/>{busqueda.length>=1&&!productoActivo&&(()=>{const q=busqueda.toLowerCase();const sugs=prods.filter(p=>p.nombre.toLowerCase().includes(q)||p.codigo.toLowerCase().includes(q)||p.ean.includes(q)).slice(0,8);if(!sugs.length)return <div style={{position:"absolute",top:"100%",left:0,right:0,background:"white",border:"1.5px solid #e2e8f0",borderRadius:8,zIndex:200,padding:"10px 14px",fontSize:12,color:"#94a3b8"}}>No encontrado</div>;return(<div style={{position:"absolute",top:"100%",left:0,right:0,background:"white",border:`1.5px solid ${rcol[miRonda]}`,borderRadius:8,boxShadow:"0 4px 16px rgba(0,0,0,0.15)",zIndex:200,maxHeight:280,overflowY:"auto"}}>{sugs.map((p,i)=>{const tot=getTotal(miConteo.id,miRonda,p.id);return(<div key={p.id} onClick={()=>{setProductoActivo(p);setForm({unidades:"",embalaje:"",cajas:"",estado:"BUENO",obs:""});setBusqueda("");setTimeout(()=>unidadesRef.current?.focus(),80);}} style={{padding:"10px 14px",cursor:"pointer",borderBottom:i<sugs.length-1?"1px solid #f1f5f9":"none",display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><div style={{fontWeight:700,fontSize:13}}>{p.nombre}</div><div style={{fontSize:11,color:"#64748b"}}><span style={{fontFamily:"monospace",color:"#2563eb",marginRight:8}}>{p.codigo}</span>{p.referencia}</div></div>{tot>0?<div style={{background:rcol[miRonda]+"22",color:rcol[miRonda],padding:"2px 8px",borderRadius:12,fontSize:11,fontWeight:700}}>✓ {tot}</div>:<div style={{color:"#d1d5db",fontSize:11}}>Sin captura</div>}</div>);})}</div>);})()}</div></div></div>
      {productoActivo&&(()=>{const totalAnt=getTotal(miConteo.id,miRonda,productoActivo.id);return(<div style={{background:"white",borderRadius:10,padding:20,marginBottom:10,boxShadow:"0 2px 8px rgba(0,0,0,0.1)",border:`2px solid ${rcol[miRonda]}`}}><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16,marginBottom:16,paddingBottom:14,borderBottom:"1px solid #f1f5f9"}}><div><div style={{fontSize:11,color:"#94a3b8"}}>CÓDIGO</div><div style={{fontFamily:"monospace",fontSize:16,fontWeight:800,color:"#2563eb"}}>{productoActivo.codigo}</div><div style={{marginTop:8}}><div style={{fontSize:11,color:"#94a3b8"}}>NOMBRE</div><div style={{fontWeight:700,fontSize:15}}>{productoActivo.nombre}</div></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginTop:8}}><div><div style={{fontSize:10,color:"#94a3b8"}}>REFERENCIA</div><div style={{fontSize:13,fontWeight:600}}>{productoActivo.referencia||"—"}</div></div><div><div style={{fontSize:10,color:"#94a3b8"}}>PROVEEDOR</div><div style={{fontSize:13,fontWeight:600}}>{productoActivo.proveedor||"—"}</div></div></div>{totalAnt>0&&<div style={{marginTop:8,background:"#eff6ff",borderRadius:8,padding:"6px 10px",fontSize:12,color:"#2563eb",fontWeight:600}}>Ya capturado: {totalAnt} und</div>}</div><div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}><div><div style={{fontSize:10,color:"#94a3b8"}}>UBICACIÓN</div><div style={{fontSize:12,fontWeight:600}}>{miConteo.ubicacion}</div></div><div><div style={{fontSize:10,color:"#94a3b8"}}>LOCALIZACIÓN</div><div style={{fontSize:12,fontWeight:600}}>{miConteo.localizacion}</div></div><div><div style={{fontSize:10,color:"#94a3b8"}}>N°</div><div style={{fontSize:12,fontWeight:600}}>{miConteo.nro}</div></div><div><div style={{fontSize:10,color:"#94a3b8"}}>CONTEO</div><div style={{fontSize:12,fontWeight:600}}>{miRonda==="C1"?1:miRonda==="C2"?2:3}</div></div></div></div></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:20}}><div><div style={{fontWeight:700,fontSize:12,color:"#374151",marginBottom:10,textTransform:"uppercase",letterSpacing:1}}>Cantidades</div><div style={{display:"grid",gridTemplateColumns:"100px 1fr",gap:8,alignItems:"center"}}><label style={{fontSize:12,fontWeight:600}}>UNIDADES</label><input ref={unidadesRef} type="number" min="0" value={form.unidades} onChange={e=>setForm(f=>({...f,unidades:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter"){if(form.cajas||form.embalaje)document.getElementById("inp-emb")?.focus();else guardar();}}} placeholder="0" style={{...inp,padding:"8px 10px",fontSize:16,fontWeight:700,textAlign:"center"}}/><label style={{fontSize:12,fontWeight:600}}>EMBALAJE</label><input id="inp-emb" type="number" min="0" value={form.embalaje} onChange={e=>setForm(f=>({...f,embalaje:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter")document.getElementById("inp-caj")?.focus();}} placeholder="Und/caja" style={{...inp,padding:"8px 10px",fontSize:14,textAlign:"center"}}/><label style={{fontSize:12,fontWeight:600}}>CAJAS</label><input id="inp-caj" type="number" min="0" value={form.cajas} onChange={e=>setForm(f=>({...f,cajas:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter")guardar();}} placeholder="Cajas" style={{...inp,padding:"8px 10px",fontSize:14,textAlign:"center"}}/><label style={{fontSize:14,fontWeight:800}}>TOTAL</label><div style={{...inp,padding:"10px",fontSize:22,fontWeight:800,textAlign:"center",background:total>0?"#eff6ff":"#f8fafc",color:total>0?rcol[miRonda]:"#94a3b8",border:`2px solid ${total>0?rcol[miRonda]:"#e2e8f0"}`,cursor:"default"}}>{total||0}</div></div></div><div><div style={{fontWeight:700,fontSize:12,color:"#374151",marginBottom:10,textTransform:"uppercase",letterSpacing:1}}>Estado</div><select value={form.estado} onChange={e=>setForm(f=>({...f,estado:e.target.value}))} style={{...inp,fontSize:13,marginBottom:10}}>{["BUENO","VENCIDO","AVERIADO","NO APTO VENTA","BAJAS","SIN REVISAR"].map(s=><option key={s}>{s}</option>)}</select><div style={{fontSize:11,color:"#94a3b8",marginBottom:4}}>OBSERVACIÓN</div><input type="text" value={form.obs} onChange={e=>setForm(f=>({...f,obs:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter")guardar();}} placeholder="Opcional…" style={{...inp,fontSize:13}}/></div></div><div style={{display:"flex",gap:10,marginTop:16,flexWrap:"wrap",alignItems:"center"}}><button onClick={guardar} disabled={(miRonda!=="C3"&&total<=0)||saving} style={{padding:"10px 28px",background:miRonda==="C3"||total>0?"#16a34a":"#e2e8f0",color:miRonda==="C3"||total>0?"white":"#94a3b8",border:"none",borderRadius:8,cursor:"pointer",fontWeight:700,fontSize:14}}>{saving?"Guardando...":"GUARDAR"}</button><button onClick={()=>{setProductoActivo(null);setForm({unidades:"",embalaje:"",cajas:"",estado:"BUENO",obs:""});setTimeout(()=>scanRef.current?.focus(),80);}} style={{padding:"10px 20px",background:"#64748b",color:"white",border:"none",borderRadius:8,cursor:"pointer",fontWeight:700,fontSize:13}}>CANCELAR</button><div style={{flex:1}}/>{soyPrincipal(miConteo)&&<button onClick={()=>setModalCerrar(true)} style={{padding:"10px 20px",background:"#dc2626",color:"white",border:"none",borderRadius:8,cursor:"pointer",fontWeight:700,fontSize:13}}>TERMINAR</button>}</div></div>);})()}

      {miRonda!=="C3"&&capsReal.length>0&&(<div style={{background:"white",borderRadius:10,overflow:"hidden",boxShadow:"0 1px 4px rgba(0,0,0,0.06)",marginBottom:10}}><div style={{padding:"10px 16px",background:"#f8fafc",borderBottom:"1px solid #e2e8f0",display:"flex",justifyContent:"space-between",alignItems:"center"}}><span style={{fontWeight:700,fontSize:13}}>Capturas realizadas — {capsReal.length} productos</span></div><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead><tr style={{background:"#f1f5f9"}}>{["Código","Nombre","Total","Estado","Acciones"].map(h=><th key={h} style={{padding:"7px 10px",textAlign:"left",fontWeight:700,fontSize:11}}>{h}</th>)}</tr></thead><tbody>{capsReal.map(({p,caps,total:tot},i)=>(<tr key={p.id} style={{background:i%2?"#f8fafc":"white",borderBottom:"1px solid #f1f5f9"}}><td style={{padding:"7px 10px",fontFamily:"monospace",color:"#2563eb",fontWeight:700,fontSize:11}}>{p.codigo}</td><td style={{padding:"7px 10px",fontWeight:600}}>{p.nombre}</td><td style={{padding:"7px 10px",textAlign:"center"}}><span style={{fontWeight:800,fontSize:14,color:rcol[miRonda]}}>{tot}</span></td><td style={{padding:"7px 10px"}}><EstBadge e={caps[0]?.estado}/></td><td style={{padding:"7px 10px"}}><button onClick={()=>{setProductoActivo(p);setForm({unidades:"",embalaje:"",cajas:"",estado:"BUENO",obs:""});setTimeout(()=>unidadesRef.current?.focus(),80);}} style={{background:"#eff6ff",color:"#2563eb",border:"none",borderRadius:6,padding:"3px 10px",cursor:"pointer",fontWeight:700,fontSize:11,marginRight:4}}>+ Agregar</button><button onClick={async()=>{caps.forEach(c=>{const k=Object.keys(G.capturas).find(k=>G.capturas[k]===c);if(k)delete G.capturas[k];});const cn=G.conteos.find(x=>x.id===miConteo.id);if(cn){cn.capturas=cn.capturas||{};caps.forEach(c=>{Object.keys(cn.capturas).forEach(k=>{if(cn.capturas[k]===c)delete cn.capturas[k];});});await persistConteo(cn);}rerender();showToast("Eliminado","warn");}} style={{background:"#fef2f2",color:"#dc2626",border:"1px solid #fecaca",borderRadius:6,padding:"3px 10px",cursor:"pointer",fontWeight:700,fontSize:11}}>Borrar</button></td></tr>))}</tbody></table>{soyPrincipal(miConteo)&&<div style={{padding:"10px 16px",background:"#f8fafc",borderTop:"1px solid #e2e8f0",display:"flex",justifyContent:"flex-end"}}><button onClick={()=>setModalCerrar(true)} style={{background:"#dc2626",color:"white",border:"none",borderRadius:8,padding:"8px 24px",cursor:"pointer",fontWeight:700,fontSize:13}}>TERMINAR CONTEO</button></div>}</div>)}

      {capsReal.length===0&&!productoActivo&&miRonda!=="C3"&&(<div style={{...card,textAlign:"center",padding:36,color:"#64748b"}}><div style={{fontSize:36,marginBottom:8}}>📷</div><div style={{fontSize:14,fontWeight:600}}>Escanea o busca un producto para comenzar</div><div style={{fontSize:12,marginTop:4}}>{prods.length} productos disponibles</div></div>)}
    </div>
    {modalCerrar&&(<div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.55)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{background:"white",borderRadius:16,padding:28,width:380,maxWidth:"96vw",boxShadow:"0 25px 60px rgba(0,0,0,0.3)"}}><h3 style={{margin:"0 0 16px",fontSize:17,fontWeight:700}}>Terminar conteo</h3><p style={{fontSize:14,color:"#374151",marginBottom:24}}>¿Estás seguro? Los datos se guardarán en la nube.</p><div style={{display:"flex",gap:10}}><Btn c="#dc2626" onClick={cerrarConteo} full disabled={saving}>{saving?"Guardando...":"Sí, terminar"}</Btn><Btn c="#64748b" onClick={()=>setModalCerrar(false)} full>Cancelar</Btn></div></div></div>)}
  </div>);
}
